function renderSidebar(active){
  let cur=window.currentSessionSummary;
  return `<div class="sidebar-brand"><div class="logo"></div><div><b>EPC / SENEVAL</b><span>Diagnostic</span></div></div>
  <nav class="sidebar-nav">${SIDEBAR_ITEMS.map(it=>`<button class="${it.key===active?'active':''}" ${it.need&&!window.currentSessionId?'disabled':''} onclick="(${it.go.toString()})()"><span class="nav-ic">${it.ic}</span>${it.label}</button>`).join('')}</nav>
  ${cur?`<div class="sidebar-current"><div class="dot-row"><span class="dot"></span>Atelier actuel</div><div class="name">${esc(cur.name)}</div><div class="meta">${esc(cur.location||'—')}${cur.date?' · '+esc(cur.date):''}</div><div class="status-row"><span>Statut</span><span class="badge-mini">${esc(cur.statusLabel||'Préparation')}</span></div><div class="progress"><span style="width:${cur.pct??0}%"></span></div><button onclick="moderator('${cur.id}')">Voir le tableau de bord →</button></div>`:''}
  ${window.currentUser?`<div class="sidebar-user"><div class="name">${esc(window.currentUser.displayName||window.currentUser.email)}</div><button class="ghost" onclick="doLogout()">Se déconnecter</button></div>`:''}`;
}
function renderTopbar(title,subtitle,cycleStage){
  let stages=[['config','CONFIGURER'],['collecte','COLLECTER'],['traiter','TRAITER'],['analyse','ANALYSER'],['restitution','RESTITUER']];
  return `<div><h1>${esc(title||'')}</h1>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><div class="cycle-nav">${stages.map(([k,l])=>`<div class="cycle-step ${k===cycleStage?'active':''}"><span class="cycle-ic">${k===cycleStage?'●':'○'}</span>${l}</div>`).join('')}</div><button class="topbar-help" title="Aide" onclick="helpPanel()">?</button>`;
}
const HELP_SCREENS={
  home:{title:'Accueil',body:`
    <p>C’est le point de départ : la liste de tous vos ateliers de diagnostic.</p>
    <p class="help-callout"><b>Le parcours général :</b> CONFIGURER → COLLECTER → TRAITER → ANALYSER → RESTITUER.</p>
    <h3>Que faire ici ?</h3>
    <ol>
      <li><b>Nouveau diagnostic</b> pour créer un atelier.</li>
      <li><b>Reprendre</b> pour continuer votre atelier le plus récent.</li>
      <li><b>Ateliers récents</b> pour rouvrir n’importe quel atelier déjà créé.</li>
      <li><b>Modèles &amp; questionnaires</b> pour consulter ou dupliquer un questionnaire.</li>
    </ol>
    <p class="help-callout"><b>À retenir :</b> reprendre un atelier existant ne fait perdre aucune information déjà enregistrée.</p>
    <p><b>Étape suivante :</b> Configuration.</p>
    <h3>Espace utilisateur</h3>
    <p>Chaque compte dispose de son propre espace : vous ne voyez que vos propres ateliers et questionnaires personnels.</p>`},
  config:{title:'Configuration de la mission',body:`
    <p>Cet écran sert à préparer la mission avant d’ouvrir la collecte auprès des participants.</p>
    <h3>Que faire, dans quel ordre ?</h3>
    <ol>
      <li><b>Informations de la mission</b> : nom, lieu, date, description.</li>
      <li><b>Participants prévus</b> : nombre indicatif, utilisé comme référence — différent du nombre réel de répondants, recalculé après la collecte.</li>
      <li><b>Questionnaire</b> : le modèle EPC / SENEVAL est utilisé par défaut. Vous pouvez le garder, en changer, ou modifier ses domaines/références/indicateurs.</li>
      <li><b>Échelle de notation</b> : renommez les niveaux ou ajustez leur nombre (2 à 9).</li>
    </ol>
    <p class="help-callout"><b>À retenir :</b> une fois que l’atelier a des réponses, le questionnaire et l’échelle sont verrouillés pour ne pas invalider les données déjà collectées — modifiez-les avant d’ouvrir la collecte.</p>
    <p><b>Étape suivante :</b> ouvrir la collecte.</p>
    <h3>Assistant IA — facultatif</h3>
    <p>L’assistant IA peut vous aider à interpréter les résultats, préparer l’analyse, explorer des hypothèses, formuler des recommandations et rédiger la synthèse du rapport. <b>Il ne modifie jamais les calculs EPC et ne décide pas à la place du groupe.</b></p>
    <ol>
      <li>Activer l’assistant IA.</li>
      <li>Choisir un fournisseur.</li>
      <li>Obtenir une clé API <span class="text-meta">(le « ? » à côté du champ Clé API explique comment, selon le fournisseur choisi)</span>.</li>
      <li>Coller la clé.</li>
      <li>Choisir le modèle recommandé.</li>
      <li>Tester l’assistant IA.</li>
    </ol>
    <p><b>Badges</b> <span class="badge ai-badge" data-pricing="GRATUIT">GRATUIT</span> <span class="badge ai-badge" data-pricing="ESSAI">ESSAI</span> <span class="badge ai-badge" data-pricing="PAYANT">PAYANT</span> : ces indications concernent l’accès à l’API du fournisseur (pas son usage grand public) et peuvent évoluer.</p>
    <p class="help-callout"><b>À retenir :</b> la clé API est personnelle. Ne la partagez pas avec les participants. Une suggestion de l’assistant IA n’est jamais enregistrée automatiquement : c’est toujours vous, le pilote, qui décidez explicitement de retenir (ou non) ce qu’il propose.</p>
    <p>Lorsque vous utilisez une fonction IA, les données nécessaires à cette analyse sont transmises au fournisseur sélectionné. Les réponses individuelles nominatives et les informations techniques inutiles ne sont pas transmises. EPC / SENEVAL fonctionne normalement si l’IA est désactivée.</p>
    <p class="help-callout"><b>En cas de problème :</b> clé API refusée → vérifiez la clé, le fournisseur, le quota ou le modèle. Assistant IA indisponible → vous pouvez poursuivre l’atelier normalement, sans IA.</p>`},
  questionnaire:{title:'Questionnaire',body:`
    <p>Cet écran présente la structure du questionnaire utilisé pour l’atelier.</p>
    <h3>Vocabulaire</h3>
    <p><b>Domaine</b> : grande thématique (ex. Gestion des ressources humaines). <b>Référence</b> : identifiant court d’une question. <b>Indicateur qualitatif / capacité</b> : la question elle-même, notée par les participants selon l’échelle définie en Configuration.</p>
    <h3>Que faire ?</h3>
    <ul>
      <li>Modifier, ajouter ou supprimer un domaine ou un indicateur.</li>
      <li>Importer une matrice Excel déjà préparée.</li>
      <li>Télécharger la matrice pour la modifier hors ligne puis la réimporter.</li>
    </ul>
    <p class="help-callout"><b>À retenir :</b> la numérotation et l’ordre d’affichage sont gérés automatiquement.</p>
    <p class="help-callout"><b>En cas de problème :</b> questionnaire vide → revenez ici pour ajouter au moins un domaine avec une question.</p>`},
  collecte:{title:'Collecte',body:`
    <p>Cet écran sert à ouvrir la collecte des réponses et à en suivre l’avancement.</p>
    <h3>Que faire, dans quel ordre ?</h3>
    <ol>
      <li>Ouvrir la collecte.</li>
      <li>Afficher ou partager le QR code / le lien participant. Le bouton « Ouvrir participant » ouvre cette vue dans un nouvel onglet, sans fermer votre tableau de bord.</li>
      <li>Les participants répondent depuis leur téléphone.</li>
      <li>Suivre le nombre de participants et de questionnaires validés.</li>
      <li>Passer aux résultats lorsque la collecte est suffisante ou terminée.</li>
    </ol>
    <p class="help-callout"><b>À retenir :</b> les participants n’ont accès qu’au questionnaire — jamais à la configuration, ni à l’assistant IA.</p>
    <p class="help-callout"><b>En cas de problème :</b> QR inaccessible → vérifiez que l’adresse de l’application est bien accessible depuis le téléphone des participants.</p>`},
  resultats:{title:'Résultats / Diagnostic',body:`
    <p><b>Capacité</b> = niveau obtenu à partir des réponses. <b>Consensus</b> = degré de convergence entre les réponses des participants.</p>
    <h3>Comment lire les deux ensemble ?</h3>
    <p class="help-callout">Capacité faible + consensus élevé → faiblesse largement partagée.</p>
    <p class="help-callout">Capacité faible + consensus faible → faiblesse possible mais perceptions divergentes.</p>
    <p class="help-callout">Capacité élevée + consensus élevé → force largement reconnue.</p>
    <p class="help-callout">Capacité élevée + consensus faible → situation globalement favorable, mais vécue différemment selon les participants.</p>
    <p>Si l’assistant IA est activé, il peut proposer une lecture de ces résultats (bouton « ✦ Analyser avec l’IA »).</p>
    <h3>Priorités et analyse</h3>
    <p>Les priorités sont choisies par les participants et le modérateur selon le processus EPC. Pour chaque priorité retenue, vous documentez un constat, puis des causes, conséquences et leviers.</p>
    <p>L’IA peut aider à reformuler le constat, préparer des questions, suggérer des hypothèses de causes, de conséquences, ou identifier des leviers.</p>
    <p class="help-callout"><b>À retenir :</b> une suggestion IA n’est jamais une cause validée. Elle doit être discutée et retenue explicitement par le groupe.</p>
    <p class="help-callout"><b>En cas de problème :</b> pas de résultats → vérifiez qu’au moins un questionnaire a été validé par un participant.</p>`},
  recommandations:{title:'Recommandations',body:`
    <p>Cet écran construit la chaîne qui relie les résultats aux actions à mener :</p>
    <p class="help-callout">PRIORITÉ → CONSTAT → CAUSES → LEVIERS → RECOMMANDATIONS</p>
    <p>L’IA peut proposer des pistes de recommandations fondées sur les causes et leviers déjà retenus, mais le groupe et le modérateur conservent la validation finale.</p>
    <h3>Formations et plan d’action</h3>
    <p>Depuis cet écran, accédez aussi aux <b>besoins / thèmes de formation</b> (repris automatiquement des recommandations de catégorie Formation) et au <b>plan d’action</b> (tableau des recommandations retenues, avec responsable et échéance).</p>
    <p><b>Étape suivante :</b> Rapport final.</p>`},
  rapport:{title:'Rapport final',body:`
    <p>Le rapport rassemble automatiquement : méthodologie, participation, résultats EPC, graphiques, priorités, analyses, recommandations, formations, plan d’action et annexes.</p>
    <p>Téléchargez-le en Word, Excel, ou PDF (impression du rapport web).</p>
    <h3>✦ Assistance IA au rapport</h3>
    <p>L’IA peut préparer une proposition de rédaction à partir des résultats et analyses déjà validés. Elle ne recalcule pas les résultats et ne doit pas inventer les informations manquantes. Vous pouvez retenir, modifier, régénérer ou ignorer chaque proposition.</p>
    <p class="help-callout"><b>DONNÉES EPC</b> → calculées automatiquement. <b>TEXTE IA</b> → proposition rédactionnelle soumise à votre validation.</p>`},
};
function helpPanel(){
  let key=window.currentHelpKey||'home',screen=HELP_SCREENS[key]||HELP_SCREENS.home;
  let n=document.querySelector('#notice');if(!n){n=document.createElement('div');n.id='notice';document.body.appendChild(n)}
  n.className='help-modal';
  n.innerHTML=`<div>
    <h2>Aide — ${esc(screen.title)}</h2>
    <p class="text-meta">Outil de diagnostic EPC / SENEVAL · le bouton « ? » ouvre toujours l’aide de l’écran où vous êtes.</p>
    ${screen.body}
    <button class="secondary help-close" onclick="this.closest('.help-modal').remove()">Fermer</button>
  </div>`;
}
function shell(active,cycleStage,title,subtitle,sessionSummary){
  document.querySelector('.app-shell')?.classList.remove('participant-mode');
  window.currentHelpKey=active;
  if(sessionSummary!==undefined)window.currentSessionSummary=sessionSummary;
  document.querySelector('#sidebar').innerHTML=renderSidebar(active);
  document.querySelector('#topbar').innerHTML=renderTopbar(title,subtitle,cycleStage);
}
function gaugeCircle(pct,size=150){
  let r=size*.36,c=2*Math.PI*r,cx=size/2,cy=size/2,off=c*(1-Math.max(0,Math.min(100,pct))/100);
  return `<svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}"><circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="var(--gray-100)" stroke-width="12"/><circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="var(--accent-600)" stroke-width="12" stroke-linecap="round" stroke-dasharray="${c.toFixed(1)}" stroke-dashoffset="${off.toFixed(1)}" transform="rotate(-90 ${cx} ${cy})"/><text x="${cx}" y="${cy-3}" text-anchor="middle" class="gauge-value">${pct}<tspan class="gauge-suffix">%</tspan></text><text x="${cx}" y="${cy+20}" text-anchor="middle" class="gauge-label">${pct>=100?'PRÊT':'À COMPLÉTER'}</text></svg>`;
}
function gaugeSemi(value,min,max,unset){
  let v=value??min,pct=unset?0:Math.max(0,Math.min(1,(v-min)/(max-min||1))),r=72,cx=90,cy=92;
  let ang=Math.PI-Math.PI*pct,x2=cx+r*Math.cos(ang),y2=cy-r*Math.sin(ang),largeArc=pct>0.5?1:0;
  return `<svg width="180" height="112" viewBox="0 0 180 112"><path d="M ${cx-r} ${cy} A ${r} ${r} 0 0 1 ${cx+r} ${cy}" fill="none" stroke="var(--gray-100)" stroke-width="14" stroke-linecap="round"/>${pct>0?`<path d="M ${cx-r} ${cy} A ${r} ${r} 0 ${largeArc} 1 ${x2} ${y2}" fill="none" stroke="var(--accent-600)" stroke-width="14" stroke-linecap="round"/>`:''}<text x="90" y="76" text-anchor="middle" font-size="${unset?18:30}" font-weight="800" fill="${unset?'var(--gray-400)':'var(--gray-900)'}">${unset?'Non défini':v}</text><text x="10" y="108" font-size="10" fill="var(--gray-400)" font-weight="700">${min}</text><text x="170" y="108" text-anchor="end" font-size="10" fill="var(--gray-400)" font-weight="700">${max}</text></svg>`;
}
function sessionStatusBadge(s,a){if(s.status==='closed')return /historique/i.test(s.name)?'<span class="badge badge-info">Historique</span>':'<span class="badge badge-success">Terminé</span>';if(/\btest\b/i.test(s.name))return '<span class="badge badge-neutral">Test</span>';if(!a||!a.participantCount)return '<span class="badge badge-neutral">Nouveau</span>';return '<span class="badge badge-progress">En cours</span>'}
function emptyState(title,text,btnLabel,btnAction){return `<div class="empty-state"><h3>${esc(title)}</h3><p>${esc(text||'')}</p>${btnLabel?`<button onclick="${btnAction}">${esc(btnLabel)}</button>`:''}</div>`}
const ICON_LAYERS='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/></svg>';
const ICON_CLOCK='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3.2 2"/></svg>';
const ICON_CHECK='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="8.5"/><path d="M8.3 12.3l2.6 2.6 5-5.4"/></svg>';
const ICON_DOC='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M6 3.5h8l4 4V20a1 1 0 0 1-1 1H6a1 1 0 0 1-1-1V4.5a1 1 0 0 1 1-1z"/><path d="M14 3.5V8h4"/><path d="M8.5 12.5h7M8.5 15.5h7"/></svg>';
function statCard(tone,icon,num,label){return `<div class="stat-card"><div class="stat-icon tone-${tone}">${icon}</div><div class="stat-body"><div class="stat-num">${num}</div><div class="stat-label">${esc(label)}</div></div></div>`}
function sessionRow(s,a){let target=s.expected_participants||(a&&a.participantCount);let pct=a&&target?Math.round(a.completedCount/target*100):0;let created=s.created_at?new Date(s.created_at).toLocaleDateString('fr-FR'):'';let code='MIS-'+s.id.slice(0,4).toUpperCase();return `<div class="session-row" onclick="moderator('${s.id}')"><div class="session-main"><div class="name">${esc(s.name)}</div><div class="meta"><span class="text-meta">${created}${created?' · ':''}${code}</span>${sessionStatusBadge(s,a)}<span>${a?a.participantCount+' participant'+(a.participantCount>1?'s':''):'—'}</span>${s.date?`<span>${esc(s.date)}</span>`:''}</div></div><div class="progress-wrap"><div class="progress"><span style="width:${pct}%"></span></div><div class="pct">${a&&target?pct+'%':'—'}</div></div><div class="row-action"><button class="ghost" onclick="event.stopPropagation();moderator('${s.id}')">Ouvrir →</button></div></div>`}
let homeShowAll=false;
async function home(){let summaries=await Promise.all(S.map(s=>api('/api/sessions/'+s.id+'/analysis').catch(()=>null)));let enriched=S.map((s,i)=>({s,a:summaries[i]}));let total=enriched.length;let done=enriched.filter(x=>x.s.status==='closed').length;let inProgress=enriched.filter(x=>x.s.status==='open'&&x.a&&x.a.participantCount>0).length;let mostRecent=enriched[0];let visible=homeShowAll?enriched:enriched.slice(0,5);app.innerHTML=`<div class="hero-lead"><h2>Que souhaitez-vous faire ?</h2></div><div class="action-grid"><div class="action-card" onclick="newSession()"><div class="icon">＋</div><h3>Nouveau diagnostic</h3><p>Créer un nouvel atelier de diagnostic</p><button onclick="event.stopPropagation();newSession()">Démarrer</button></div>${mostRecent?`<div class="action-card" onclick="moderator('${mostRecent.s.id}')"><div class="icon">↻</div><h3>Reprendre</h3><p>${esc(mostRecent.s.name)}<br><span class="text-meta">${mostRecent.s.created_at?new Date(mostRecent.s.created_at).toLocaleDateString('fr-FR')+' · ':''}MIS-${mostRecent.s.id.slice(0,4).toUpperCase()}</span><br>${sessionStatusBadge(mostRecent.s,mostRecent.a)} ${mostRecent.a?`· ${mostRecent.a.completedCount}/${mostRecent.a.participantCount} validés`:''}</p><button class="secondary" onclick="event.stopPropagation();moderator('${mostRecent.s.id}')">Continuer</button></div>`:''}</div><div class="stats-grid">${statCard('blue',ICON_LAYERS,total,'Ateliers au total')}${statCard('orange',ICON_CLOCK,inProgress,'En cours')}${statCard('green',ICON_CHECK,done,'Terminés')}${statCard('neutral',ICON_DOC,T.length,'Modèles disponibles')}</div><div class="card"><div class="section-header"><h2>Ateliers récents</h2>${enriched.length>5?`<button class="ghost" onclick="homeShowAll=!homeShowAll;home()">${homeShowAll?'Réduire':'Voir tous les ateliers'}</button>`:''}</div>${enriched.length?`<div class="session-list">${visible.map(({s,a})=>sessionRow(s,a)).join('')}</div>`:emptyState('Aucun diagnostic pour le moment','Créez votre premier atelier pour commencer.','Nouveau diagnostic','newSession()')}</div><div class="card"><div class="section-header"><h3>Modèles &amp; questionnaires</h3></div>${T.length?T.map(t=>`<div class="row"><div style="flex:2;min-width:200px"><b>${esc(t.name)}</b><div class="text-meta">Modèle disponible · v${t.version}</div></div><button class="ghost" onclick="newSession('${t.id}')">Utiliser</button><button class="ghost" onclick="dup('${t.id}')">Dupliquer</button><button class="ghost" onclick="edit('${t.id}')">Modifier</button></div>`).join(''):emptyState('Aucun modèle disponible','Importez un questionnaire pour commencer.')}<div class="row" style="margin-top:.6rem"><button class="secondary" onclick="importer()">Importer un questionnaire</button><a href="/api/templates/matrix.xlsx"><button type="button" class="secondary">Créer à partir d’un modèle Excel</button></a><button class="ghost" onclick="models()">Voir tous les modèles</button></div></div>`}
function createModel(){app.innerHTML=`<section class="card">${back}<h2>Nouveau questionnaire</h2><form onsubmit="makeModel(event)"><label>Nom du questionnaire<input name="name" required></label><h3>Échelle de notation</h3>${[[5,'Totalement d’accord'],[4,'D’accord'],[3,'Neutre'],[2,'N’est pas d’accord'],[1,'Totalement en désaccord']].map(x=>`<label>${x[0]}<input name="note${x[0]}" value="${x[1]}"></label>`).join('')}<button>Enregistrer</button></form></section>`};async function makeModel(e){e.preventDefault();let f=Object.fromEntries(new FormData(e.target)),x=await api('/api/templates',{method:'POST',body:JSON.stringify({name:f.name})});window.model=await api('/api/templates/'+x.id);window.model.scale.labels={1:f.note1,2:f.note2,3:f.note3,4:f.note4,5:f.note5};await api('/api/templates/'+x.id,{method:'PUT',body:JSON.stringify({name:f.name,description:'',scale:window.model.scale,priority:window.model.priority})});edit(x.id)}
function models(){shell('questionnaire','config','Modèles & questionnaires','Bibliothèque des questionnaires disponibles');app.innerHTML=`<section class="card">${back}<h2>Modèles &amp; paramètres</h2>${T.map(t=>`<div class="row"><span><b>${esc(t.name)}</b> · v${t.version}</span><button onclick="edit('${t.id}')">Ouvrir</button><button class="secondary" onclick="dup('${t.id}')">Dupliquer</button><a href="/api/templates/${t.id}/matrix.xlsx"><button type="button" class="secondary">Exporter XLSX</button></a><button class="danger" onclick="removeModel('${t.id}','${esc(t.name)}')">Supprimer</button></div>`).join('')}</section>`};async function dup(id){let x=await api('/api/templates/'+id+'/clone',{method:'POST',body:'{}'});edit(x.id)};async function edit(id){window.model=await api('/api/templates/'+id);renderModel()};async function removeModel(id,name){if(!confirm('Supprimer le questionnaire "'+name+'" ?\n\nCette action supprimera cette configuration si elle n’est utilisée par aucune session.'))return;try{await api('/api/templates/'+id,{method:'DELETE'});await load()}catch(e){if(e.message.includes('modèle de référence'))return notice(e.message);if(confirm(e.message+'\n\nVoulez-vous le retirer de la liste des modèles tout en conservant les sessions historiques ?')){await api('/api/templates/'+id+'?force=1',{method:'DELETE'});await load()}}}
function renderModel(){let t=window.model;let ready=t.domains.some(d=>d.active&&d.indicators.some(i=>i.active));shell('questionnaire','config',t.name,'Structure du questionnaire');app.innerHTML=`<section class="card">${back}<h2>QUESTIONNAIRE : ${esc(t.name)}</h2><h3>Échelle</h3>${Array.from({length:t.scale.max-t.scale.min+1},(_,k)=>t.scale.max-k).map(n=>`<div>${n} — ${esc(t.scale.labels?.[n]||'')}</div>`).join('')}<hr>${t.domains.map(d=>`<section class="domain"><h3>${esc(d.label)}</h3><div class="row"><button class="secondary" onclick="editDomainForm('${d.id}')">Modifier le nom</button><button class="danger" onclick="delDomain('${d.id}')">Supprimer</button><button class="secondary" onclick="moveDomain('${d.id}',-1)">↑</button><button class="secondary" onclick="moveDomain('${d.id}',1)">↓</button></div>${d.indicators.filter(i=>i.active).map((i,n)=>`<div class="indicator"><b>${n+1}. ${esc(i.label)}</b><br><span class="text-meta">Référence : ${esc(i.code)}</span><div class="row"><button class="secondary" onclick="indicator('${d.id}','${i.id}')">Modifier</button><button class="danger" onclick="del('${i.id}')">Supprimer</button><button class="secondary" onclick="moveIndicator('${i.id}',-1)">↑</button><button class="secondary" onclick="moveIndicator('${i.id}',1)">↓</button></div></div>`).join('')}<button onclick="indicator('${d.id}')">+ Ajouter une référence / question</button></section>`).join('')}<button onclick="editDomainForm()">+ Ajouter un domaine</button><hr><button ${ready?'':'disabled'} onclick="newSession('${t.id}')">Valider le questionnaire et démarrer un atelier →</button>${ready?'':'<p class="muted">Ajoutez au moins un domaine avec une question pour démarrer un atelier.</p>'}</section>`}
async function saveModel(e){e.preventDefault();let f=Object.fromEntries(new FormData(e.target)),t=window.model,labels;try{labels=JSON.parse(f.labels||'{}')}catch(_){return alert('Les libellés doivent être un JSON valide.')}let x=await api('/api/templates/'+t.id,{method:'PUT',body:JSON.stringify({name:f.name,description:f.description,scale:{type:'numeric',min:+f.min,max:+f.max,labels},priority:t.priority})});if(x.versionCreated)alert('Nouvelle version créée.');await edit(x.id)}
function editDomainForm(id){let d=window.model.domains.find(x=>x.id===id)||{};app.innerHTML=`<section class="card"><button class="secondary" onclick="renderModel()">← Retour</button><h2>${id?'Modifier le domaine':'Ajouter un domaine'}</h2><form onsubmit="saveDomain(event,'${id||''}')"><label>Nom du domaine<input name="label" required value="${esc(d.label||'')}"></label><button class="secondary" type="button" onclick="renderModel()">Annuler</button><button>${id?'Enregistrer':'Ajouter'}</button></form></section>`};async function saveDomain(e,id){e.preventDefault();let f=Object.fromEntries(new FormData(e.target));if(!f.label.trim())return alert('Veuillez donner un nom au domaine.');if(id){let d=window.model.domains.find(x=>x.id===id);await api('/api/domains/'+id,{method:'PUT',body:JSON.stringify({label:f.label,description:d.description,displayOrder:d.display_order,active:true})})}else await api('/api/templates/'+window.model.id+'/domains',{method:'POST',body:JSON.stringify({label:f.label})});edit(window.model.id)};async function delDomain(id){if(!confirm('Supprimer ce domaine et toutes ses questions ?'))return;try{await api('/api/domains/'+id,{method:'DELETE'})}catch(e){if(!confirm(e.message+'\n\nDésactiver ce domaine à la place (conserve l’historique) ?'))return;let d=window.model.domains.find(x=>x.id===id);await api('/api/domains/'+id,{method:'PUT',body:JSON.stringify({label:d.label,description:d.description,displayOrder:d.display_order,active:false})})}edit(window.model.id)}
function indicator(did,iid){let i=window.model.domains.flatMap(d=>d.indicators).find(x=>x.id===iid)||{};app.innerHTML=`<section class="card"><button class="secondary" onclick="renderModel()">← Retour</button><h2>${iid?'Modifier la question':'Ajouter une référence / question'}</h2><form onsubmit="saveIndicator(event,'${iid||''}')"><input type="hidden" name="domainId" value="${did}"><label>Référence<input name="code" required value="${esc(i.code||'')}"></label><label>Question / indicateur<textarea name="label" required>${esc(i.label||'')}</textarea></label><button class="secondary" type="button" onclick="renderModel()">Annuler</button><button>${iid?'Enregistrer':'Ajouter'}</button></form></section>`};async function saveIndicator(e,id){e.preventDefault();let f=Object.fromEntries(new FormData(e.target)),i=window.model.domains.flatMap(d=>d.indicators).find(x=>x.id===id)||{};if(!f.code.trim()||!f.label.trim())return notice('Veuillez renseigner la référence et la question.');let d={domainId:f.domainId,code:f.code,label:f.label,description:i.description||'',responseType:'numeric',required:true,active:true,displayOrder:i.display_order||1};if(id)await api('/api/indicators/'+id,{method:'PUT',body:JSON.stringify(d)});else await api('/api/domains/'+f.domainId+'/indicators',{method:'POST',body:JSON.stringify(d)});edit(window.model.id)};async function del(id){if(!confirm('Supprimer cette question ?'))return;try{await api('/api/indicators/'+id,{method:'DELETE'})}catch(e){if(!confirm(e.message+'\n\nDésactiver cette question à la place (conserve l’historique) ?'))return;let d=window.model.domains.find(x=>x.indicators.some(y=>y.id===id)),i=d.indicators.find(y=>y.id===id);await api('/api/indicators/'+id,{method:'PUT',body:JSON.stringify({domainId:d.id,code:i.code,label:i.label,description:i.description,responseType:i.response_type,required:i.required,active:false,displayOrder:i.display_order})})}edit(window.model.id)}
async function moveDomain(id,delta){let a=window.model.domains,b=a.findIndex(x=>x.id===id),o=a[b+delta];if(!o)return;let x=a[b];await api('/api/domains/'+x.id,{method:'PUT',body:JSON.stringify({label:x.label,description:x.description,displayOrder:o.display_order,active:true})});await api('/api/domains/'+o.id,{method:'PUT',body:JSON.stringify({label:o.label,description:o.description,displayOrder:x.display_order,active:true})});edit(window.model.id)}
async function moveIndicator(id,delta){let d=window.model.domains.find(x=>x.indicators.some(i=>i.id===id)),a=d.indicators.filter(i=>i.active),b=a.findIndex(x=>x.id===id),o=a[b+delta];if(!o)return;let x=a[b],put=i=>api('/api/indicators/'+i.id,{method:'PUT',body:JSON.stringify({domainId:d.id,code:i.code,label:i.label,description:i.description,responseType:i.response_type,required:i.required,active:true,displayOrder:i.display_order})});let xo=x.display_order;x.display_order=o.display_order;o.display_order=xo;await put(x);await put(o);edit(window.model.id)}
function importer(){app.innerHTML=`<section class="card">${back}<h2>Importer un questionnaire</h2><form onsubmit="up(event)"><input type="file" name="f" accept=".xlsx" required><button>Contrôler et prévisualiser</button></form></section>`};async function up(e){e.preventDefault();let r=await fetch('/api/templates/import/preview',{method:'POST',body:new FormData(e.target)}),x=await r.json();if(!r.ok)return alert(x.error);app.innerHTML=`<section class="card">${back}<h2>Aperçu</h2>${x.errors.length?`<p class="error">${x.errors.join('<br>')}</p>`:`<p class="ok">${x.rows} indicateurs valides ; rien n’est enregistré.</p>`}<button ${x.errors.length?'disabled':''} onclick="confirmImport('${x.token}')">Valider l’import</button></section>`};async function confirmImport(token){let x=await api('/api/templates/import/confirm',{method:'POST',body:JSON.stringify({token})});edit(x.id)}
function newSession(selectedId){shell('home','','Nouveau diagnostic','Donnez un nom à votre atelier pour commencer');app.innerHTML=`<section class="card">${back}<h2>Nouveau diagnostic</h2><form onsubmit="makeSession(event,'${selectedId||''}')"><label>Objet de la mission<input name="name" required autofocus placeholder="Ex : Atelier Dakar"></label><p class="text-meta">${selectedId?'':'Le questionnaire EPC / SENEVAL est utilisé par défaut — vous pourrez le changer ou en créer un nouveau depuis la Configuration, à l’étape suivante.'}</p><button>Créer l’atelier →</button></form></section>`};async function makeSession(e,selectedId){e.preventDefault();let f=Object.fromEntries(new FormData(e.target));let templateId=selectedId||T.find(t=>t.is_canonical)?.id||T[0]?.id;if(!templateId)return notice('Aucun questionnaire disponible pour démarrer. Créez-en un depuis Modèles & questionnaires.');let x=await api('/api/sessions',{method:'POST',body:JSON.stringify({name:f.name,templateId})});configuration(x.id)}

async function configuration(id){
  let list=await api('/api/sessions'),s=list.find(x=>x.id===id);
  if(!s)return notice('Atelier introuvable.');
  let t=await api('/api/templates/'+s.template_id);
  let a=await api('/api/sessions/'+id+'/analysis').catch(()=>null);
  window.configHasData=!!(a&&a.participantCount>0);
  let aiCfg=await api('/api/ai/config').catch(()=>({enabled:false,provider:null,model:null,keyConfigured:false,providers:{}}));
  window.aiCfg=aiCfg;
  window.scaleLocked=!!(a&&a.global&&a.global.responses>0);
  window.currentSessionId=id;
  let domains=t.domains.filter(d=>d.active);
  let totalInd=domains.reduce((n,d)=>n+d.indicators.filter(i=>i.active).length,0);
  let expected=s.expected_participants,sliderVal=expected||20;
  window.scaleDraft={min:+t.scale.min,max:+t.scale.max,labels:{...(t.scale.labels||{})}};
  let steps=[
    {label:'Mission',sub:'Défini',done:!!(s.name&&s.location)},
    {label:'Questionnaire',sub:'Sélectionné',done:domains.length>0&&totalInd>0},
    {label:'Participants',sub:'Paramétrés',done:!!s.expected_participants},
    {label:'Vérification',sub:'En attente',done:false},
  ];
  let doneCount=steps.filter(x=>x.done).length,pct=Math.round(doneCount/steps.length*100);
  let ready=domains.length>0&&totalInd>0;
  shell('config','config','CONFIGURATION DE LA MISSION','Paramétrez votre mission avant de lancer la collecte',{id,name:s.name,location:s.location,date:s.date,pct,statusLabel:'Préparation'});
  app.innerHTML=`${window.configHasData?`<div class="card" style="border-left:4px solid var(--orange-600);background:var(--orange-50);margin-bottom:1rem"><b>⚠ Cet atelier contient déjà des données réelles</b><p class="muted small" style="margin:.3rem 0 0">${a.participantCount} participant${a.participantCount>1?'s':''} · ${a.completedCount} questionnaire${a.completedCount>1?'s':''} validé${a.completedCount>1?'s':''}. Modifier le nom ci-dessous renomme cet atelier existant — cela ne crée pas un nouvel atelier vierge. Pour démarrer un diagnostic entièrement neuf, utilisez « Nouveau diagnostic » depuis l’accueil.</p></div>`:''}<div class="cfg-grid-71"><div class="card"><div class="row" style="align-items:center;gap:1.6rem;flex-wrap:wrap">${gaugeCircle(pct)}<div style="flex:1;min-width:240px"><h2>Préparation de la mission</h2><p class="muted small">Vérifiez et ajustez les paramètres de votre atelier avant d’ouvrir la collecte.</p><div class="hstepper">${steps.map((st,i)=>`<div class="hstep ${st.done?'done':((i===0||steps[i-1].done)&&!st.done?'current':'')}"><span class="circle">${st.done?'✓':i+1}</span><span class="hlabel">${st.label}<br>${st.sub}</span></div>`).join('')}</div></div></div></div><div class="card"><h3>Aperçu de votre mission</h3><div class="overview-list"><div class="ov-row"><span class="ov-label">Objet de la mission</span><span class="ov-value">${esc(s.name)}</span></div><div class="ov-row"><span class="ov-label">Questionnaire</span><span class="ov-value">${esc(t.name)} v${t.version}</span></div><div class="ov-row"><span class="ov-label">Domaines</span><span class="ov-value">${domains.length}</span></div><div class="ov-row"><span class="ov-label">Indicateurs</span><span class="ov-value">${totalInd}</span></div><div class="ov-row"><span class="ov-label">Participants prévus</span><span class="ov-value">${s.expected_participants||'—'}</span></div><div class="ov-row"><span class="ov-label">Échelle de notation</span><span class="ov-value">${t.scale.min} à ${t.scale.max}</span></div></div></div></div><div class="cfg-grid-3"><div class="card"><div class="section-header"><h3>1 · Informations de la mission</h3></div><form onsubmit="saveConfigInfo(event,'${id}')"><label>Objet de la mission<input name="name" required value="${esc(s.name)}"></label><div class="row row-fields"><label>Lieu<input name="location" value="${esc(s.location||'')}"></label><label>Date<input name="date" type="date" value="${esc(s.date||'')}"></label></div><label>Description (optionnelle)<textarea name="description">${esc(s.description||'')}</textarea></label><button class="secondary" type="submit">Enregistrer</button></form></div><div class="card" style="text-align:center"><div class="section-header" style="text-align:left"><h3>2 · Participants</h3></div><div id="participants-gauge">${gaugeSemi(sliderVal,1,100,!expected)}</div><input id="participants-range" type="range" min="1" max="100" value="${sliderVal}" style="width:100%" oninput="updateParticipantsGauge(this.value)"><input id="participants-number" type="number" min="1" placeholder="Non défini" value="${expected||''}" style="width:100%;margin-top:.5rem" onchange="document.querySelector('#participants-range').value=this.value||20;updateParticipantsGauge(this.value||20)"><p class="text-meta" style="margin-top:.6rem;text-align:left">Ce nombre sert de référence pour les analyses. Le nombre réel de participants reste calculé à partir des données collectées.</p><button class="secondary block" onclick="saveExpectedParticipants('${id}')">Enregistrer</button></div><div class="card"><div class="section-header"><h3>3 · Structure du questionnaire</h3></div><div class="pill-row"><div class="stat-pill"><div class="pill-ic">${ICON_LAYERS}</div><div><b>${domains.length}</b><span>Domaines</span></div></div><div class="stat-pill"><div class="pill-ic">${ICON_DOC}</div><div><b>${totalInd}</b><span>Indicateurs</span></div></div></div><p class="text-meta">Répartition par domaine</p>${domains.map((d,i)=>{let n=d.indicators.filter(x=>x.active).length,max=Math.max(...domains.map(x=>x.indicators.filter(y=>y.active).length),1);return `<div class="domain-bar-row"><span class="db-label">${i+1}. ${esc(d.label)}</span><span class="db-track"><span class="db-fill" style="width:${n/max*100}%;background:${DOMAIN_COLORS[i%7]}"></span></span><span class="db-count">${n}</span></div>`}).join('')}<button class="secondary block" style="margin-top:.8rem" onclick="edit('${t.id}')">Voir / Modifier le questionnaire →</button>${scaleLocked?`<p class="text-meta" style="margin-top:.6rem">Cet atelier a déjà des réponses : le questionnaire ne peut plus être changé ou recréé.</p>`:`<div class="row" style="margin-top:.5rem;gap:.5rem;flex-wrap:wrap"><button class="ghost" onclick="pickQuestionnaire('${id}')">🔁 Changer de questionnaire</button><button class="ghost" onclick="createQuestionnaireForSession('${id}')">+ Nouveau questionnaire</button></div>`}</div></div><div class="cfg-grid-71"><div class="card"><div class="section-header"><h3>4 · Échelle de notation</h3></div>${scaleLocked?`<p class="muted small">Cet atelier a déjà des réponses enregistrées. L’échelle de notation ne peut plus être modifiée : la changer invaliderait ces réponses.</p><div class="scale-cards" style="--scale-cols:${scaleDraft.max-scaleDraft.min+1}">${Array.from({length:scaleDraft.max-scaleDraft.min+1},(_,k)=>{let v=scaleDraft.min+k,tone=scaleTone(k+1,scaleDraft.max-scaleDraft.min+1);return `<div class="scale-card sc-${tone}"><div class="sc-num">${v}</div><div class="sc-label">${esc(scaleDraft.labels?.[v]||'')}</div><div class="sc-emoji">${SCALE_EMOJI[tone-1]}</div></div>`}).join('')}</div>`:`<p class="muted small">Les participants noteront chaque indicateur selon l’échelle suivante. Renommez les niveaux ou ajustez leur nombre selon vos besoins.</p><form onsubmit="saveScale(event,'${id}','${t.id}')"><div class="scale-cards" id="scale-cards" style="--scale-cols:${scaleDraft.max-scaleDraft.min+1}">${renderScaleCards(scaleDraft.min,scaleDraft.max,scaleDraft.labels)}</div><div class="row" style="margin-top:.7rem;flex-wrap:wrap;gap:.5rem"><button type="button" class="secondary" onclick="removeScaleLevel()">− Retirer un niveau</button><button type="button" class="secondary" onclick="addScaleLevel()">+ Ajouter un niveau</button><button class="secondary" type="submit" style="margin-left:auto">Enregistrer l’échelle</button></div></form>`}</div><div class="card launch-block"><div class="launch-ic">🛡️</div><h3>Prêt à ouvrir la collecte ?</h3><p class="muted small">Vérifiez que tous les paramètres sont corrects puis ouvrez la collecte pour les participants.</p><button class="primary-lg" onclick="launchCollecte('${id}',${ready})">🚀 Ouvrir la collecte</button><button class="secondary" onclick="preview('${id}')">👁 Aperçu du questionnaire</button></div></div>${aiConfigCardHtml(aiCfg)}<p class="text-meta" style="margin-top:.5rem;display:flex;justify-content:space-between;flex-wrap:wrap;gap:.4rem"><span>Vous pourrez ajuster certains paramètres pendant l’atelier. Toute modification du questionnaire sera versionnée.</span><span>Dernière sauvegarde : ${new Date().toLocaleString('fr-FR')}</span></p>`;
}
const SCALE_EMOJI=['😞','🙁','😐','🙂','😄'];
function scaleTone(i,count){return count<=1?3:Math.round(1+(i-1)/(count-1)*4)}
function renderScaleCards(min,max,labels){let n=max-min+1;return Array.from({length:n},(_,k)=>{let v=min+k,tone=scaleTone(k+1,n);return `<div class="scale-card sc-${tone}"><div class="sc-num">${v}</div><input class="sc-label-input" data-level="${v}" value="${esc(labels?.[v]??labels?.[String(v)]??'')}" placeholder="Libellé du niveau ${v}"><div class="sc-emoji">${SCALE_EMOJI[tone-1]}</div></div>`}).join('')}
function refreshScaleCards(){let el=document.querySelector('#scale-cards');el.style.setProperty('--scale-cols',scaleDraft.max-scaleDraft.min+1);el.innerHTML=renderScaleCards(scaleDraft.min,scaleDraft.max,scaleDraft.labels)}
function collectScaleLabels(){let labels={};document.querySelectorAll('.sc-label-input').forEach(inp=>{labels[inp.dataset.level]=inp.value});return labels}
function addScaleLevel(){if(scaleDraft.max-scaleDraft.min+1>=9)return notice('Le nombre maximum de niveaux est 9.');scaleDraft.labels=collectScaleLabels();scaleDraft.max+=1;refreshScaleCards()}
function removeScaleLevel(){if(scaleDraft.max-scaleDraft.min+1<=2)return notice('Il faut conserver au moins 2 niveaux.');scaleDraft.labels=collectScaleLabels();scaleDraft.max-=1;delete scaleDraft.labels[scaleDraft.max+1];refreshScaleCards()}
async function saveScale(e,id,tid){e.preventDefault();if(window.scaleLocked)return notice('Impossible de modifier l’échelle : cet atelier a déjà des réponses enregistrées.');let labels=collectScaleLabels();if(Object.values(labels).some(v=>!v.trim()))return notice('Veuillez renseigner un libellé pour chaque niveau.');let x=await api('/api/templates/'+tid,{method:'PUT',body:JSON.stringify({scale:{type:'numeric',min:scaleDraft.min,max:scaleDraft.max,labels}})});if(x.id!==tid){let cur=(await api('/api/sessions')).find(s=>s.id===id);await api('/api/sessions/'+id,{method:'PUT',body:JSON.stringify({name:cur.name,organization:cur.organization,location:cur.location,date:cur.date,description:cur.description,expectedParticipants:cur.expected_participants,templateId:x.id})})}notice('Échelle de notation enregistrée.');configuration(id)}
async function pickQuestionnaire(id){let list=await api('/api/templates');shell('config','config','Changer de questionnaire','Choisissez le questionnaire à utiliser pour cet atelier');app.innerHTML=`<section class="card"><button class="secondary" onclick="configuration('${id}')">← Retour à la configuration</button><h2>Changer de questionnaire</h2><form onsubmit="applyQuestionnaire(event,'${id}')"><label>Questionnaire<select name="templateId">${list.map(t=>`<option value="${t.id}">${esc(t.name)} v${t.version}</option>`).join('')}</select></label><p class="text-meta">Changer de questionnaire remplace les domaines, indicateurs et l’échelle utilisés par cet atelier.</p><button>Utiliser ce questionnaire →</button></form></section>`}
async function applyQuestionnaire(e,id){e.preventDefault();if(window.scaleLocked)return notice('Impossible de changer de questionnaire : cet atelier a déjà des réponses enregistrées.');let f=Object.fromEntries(new FormData(e.target));let cur=(await api('/api/sessions')).find(s=>s.id===id);await api('/api/sessions/'+id,{method:'PUT',body:JSON.stringify({name:cur.name,organization:cur.organization,location:cur.location,date:cur.date,description:cur.description,expectedParticipants:cur.expected_participants,templateId:f.templateId})});notice('Questionnaire mis à jour.');configuration(id)}
function createQuestionnaireForSession(id){shell('config','config','Nouveau questionnaire','Créer un questionnaire vierge pour cet atelier');app.innerHTML=`<section class="card"><button class="secondary" onclick="configuration('${id}')">← Retour à la configuration</button><h2>Nouveau questionnaire</h2><form onsubmit="makeQuestionnaireForSession(event,'${id}')"><label>Nom du questionnaire<input name="name" required autofocus placeholder="Ex : Diagnostic EPC / Atelier Dakar"></label><p class="text-meta">Vous pourrez ensuite ajouter des domaines et des indicateurs, ou importer une matrice XLSX.</p><button>Créer →</button></form></section>`}
async function makeQuestionnaireForSession(e,id){e.preventDefault();if(window.scaleLocked)return notice('Impossible de créer un nouveau questionnaire : cet atelier a déjà des réponses enregistrées.');let f=Object.fromEntries(new FormData(e.target));let x=await api('/api/templates',{method:'POST',body:JSON.stringify({name:f.name})});let cur=(await api('/api/sessions')).find(s=>s.id===id);await api('/api/sessions/'+id,{method:'PUT',body:JSON.stringify({name:cur.name,organization:cur.organization,location:cur.location,date:cur.date,description:cur.description,expectedParticipants:cur.expected_participants,templateId:x.id})});notice('Nouveau questionnaire créé et associé à l’atelier. Ajoutez vos domaines et indicateurs.');edit(x.id)}
function updateParticipantsGauge(v){document.querySelector('#participants-gauge').innerHTML=gaugeSemi(+v,1,100,false);document.querySelector('#participants-number').value=v}
function aiConfigCardHtml(aiCfg){
  let providers=aiCfg.providers||{},curProvider=aiCfg.provider||Object.keys(providers)[0]||'',models=(providers[curProvider]||{}).models||[];
  return `<div class="cfg-grid-71"><div class="card"><div class="section-header"><h3>5 · Assistant IA</h3></div><p class="muted small">L’assistant IA est facultatif. EPC / SENEVAL fonctionne intégralement sans intelligence artificielle.</p><form onsubmit="saveAiConfig(event)"><label class="row" style="align-items:center;gap:.5rem"><input type="checkbox" name="enabled" style="width:auto" ${aiCfg.enabled?'checked':''} onchange="document.querySelector('#ai-fields').style.display=this.checked?'':'none'"> Activer l’assistant IA</label><div id="ai-fields" style="${aiCfg.enabled?'':'display:none'};margin-top:.6rem"><div class="row row-fields"><label>Fournisseur IA <span id="ai-provider-badge" class="ai-badge" data-pricing="${esc((providers[curProvider]||{}).pricing||'')}">${esc((providers[curProvider]||{}).pricing||'')}</span><select name="provider" id="ai-provider-select" onchange="updateAiModelOptions()">${Object.entries(providers).map(([k,v])=>`<option value="${k}" ${k===curProvider?'selected':''}>${esc(v.label)} — ${v.pricing}</option>`).join('')}</select></label><label>Modèle<select name="model" id="ai-model-select">${models.map(([mid,mlabel])=>`<option value="${esc(mid)}" ${mid===aiCfg.model?'selected':''}>${esc(mlabel)} (${esc(mid)})</option>`).join('')}</select></label></div><label>Clé API<div class="row" style="gap:.4rem"><input type="password" name="apiKey" id="ai-key-input" placeholder="${aiCfg.keyConfigured?'•••••••••••••••••••• (déjà configurée — laisser vide pour la conserver)':'Collez votre clé API ici'}" style="flex:1"><button type="button" class="secondary" onclick="toggleAiKeyVisibility()">👁</button><button type="button" class="secondary" onclick="aiKeyHelp()">?</button></div></label><div class="row" style="margin-top:.5rem;gap:.5rem;flex-wrap:wrap"><button class="secondary" type="submit">Enregistrer</button><button class="secondary" type="button" onclick="testAiConnection()">Tester l’assistant IA</button></div><p id="ai-test-status" class="text-meta" style="margin-top:.5rem"></p></div></form></div></div>`;
}
async function saveAiConfig(e){e.preventDefault();let f=Object.fromEntries(new FormData(e.target));let body={enabled:!!f.enabled,provider:f.provider,model:f.model};if(f.apiKey)body.apiKey=f.apiKey;await api('/api/ai/config',{method:'PUT',body:JSON.stringify(body)});notice('Configuration de l’assistant IA enregistrée.');configuration(window.currentSessionId)}
async function testAiConnection(){let status=document.querySelector('#ai-test-status');status.textContent='Test en cours…';status.style.color='';try{let r=await api('/api/ai/test',{method:'POST',body:'{}'});if(r.ok){status.textContent=`✓ Assistant IA opérationnel — ${r.provider} · ${r.model} · ${r.latencyMs} ms`;status.style.color='var(--green-700)'}else{status.textContent='⚠ '+r.reason;status.style.color='var(--red-600)'}}catch(e){status.textContent='⚠ '+e.message;status.style.color='var(--red-600)'}}
function toggleAiKeyVisibility(){let el=document.querySelector('#ai-key-input');el.type=el.type==='password'?'text':'password'}
function updateAiModelOptions(){let providerId=document.querySelector('#ai-provider-select').value,provider=(window.aiCfg.providers||{})[providerId]||{},models=provider.models||[];document.querySelector('#ai-model-select').innerHTML=models.map(([mid,mlabel])=>`<option value="${esc(mid)}">${esc(mlabel)} (${esc(mid)})</option>`).join('');let badge=document.querySelector('#ai-provider-badge');if(badge){badge.textContent=provider.pricing||'';badge.dataset.pricing=provider.pricing||''}}
function aiKeyHelp(){let providerId=document.querySelector('#ai-provider-select').value,p=(window.aiCfg.providers||{})[providerId];if(!p)return;let n=document.querySelector('#notice');if(!n){n=document.createElement('div');n.id='notice';document.body.appendChild(n)}n.className='notice';n.innerHTML=`<div><b>Obtenir une clé API ${esc(p.label)}</b><p>1. Ouvrez la page officielle du fournisseur.
2. Connectez-vous ou créez votre compte.
3. Créez une clé API.
4. Copiez-la.
5. Revenez ici et collez-la dans le champ Clé API.</p><div class="row" style="margin-top:.6rem;flex-wrap:wrap"><a href="${esc(p.keyUrl)}" target="_blank" rel="noopener"><button type="button" class="secondary">Ouvrir la page officielle de création de clé</button></a><button onclick="this.closest('.notice').remove()">Fermer</button></div></div>`}

// ==================================================
// Assistant IA — suggestions (facultatif, jamais de validation automatique)
// ==================================================
function aiConfirmConfidentiality(sid){
  if(localStorage.getItem('epc_ai_confirmed_'+sid))return Promise.resolve(true);
  return new Promise(resolve=>{
    let n=document.querySelector('#notice');if(!n){n=document.createElement('div');n.id='notice';document.body.appendChild(n)}
    n.className='notice';
    n.innerHTML=`<div><b>Confidentialité</b><p>L’utilisation de l’assistant IA transmet au fournisseur sélectionné les données nécessaires à l’analyse. Les réponses individuelles nominatives ne doivent pas être transmises.</p><div class="row" style="margin-top:.6rem;flex-wrap:wrap"><button class="secondary" id="ai-confirm-cancel">Annuler</button><button id="ai-confirm-ok">J’ai compris — utiliser l’assistant IA</button></div></div>`;
    document.querySelector('#ai-confirm-cancel').onclick=()=>{n.remove();resolve(false)};
    document.querySelector('#ai-confirm-ok').onclick=()=>{localStorage.setItem('epc_ai_confirmed_'+sid,'1');n.remove();resolve(true)};
  });
}
async function aiRun(sid,endpoint,body,onResult,btn){
  let ok=await aiConfirmConfidentiality(sid); if(!ok)return;
  let orig=btn?btn.textContent:null; if(btn){btn.disabled=true;btn.textContent='Génération en cours…'}
  try{ onResult(await api(endpoint,{method:'POST',body:JSON.stringify(body||{})})) }
  catch(e){ notice('Assistant IA momentanément indisponible. Vous pouvez poursuivre l’atelier normalement.\n\n('+e.message+')') }
  finally{ if(btn){btn.disabled=false;btn.textContent=orig} }
}
function aiButtonHtml(label,onclick,extraId){return `<button class="secondary ai-btn" ${extraId?`id="${extraId}"`:''} onclick="${onclick}">✦ ${esc(label)}</button>`}
function aiInfoCardHtml(boxId,text,regenFn){return `<div class="card ai-suggestion"><div class="section-header"><h3>✦ Lecture assistée par IA</h3></div><div style="white-space:pre-line">${esc(text)}</div><p class="text-meta" style="margin-top:.6rem">Analyse proposée par l’IA à partir des résultats EPC. Elle ne constitue pas une conclusion validée par le groupe.</p><div class="row" style="margin-top:.6rem;flex-wrap:wrap"><button class="secondary" onclick="${regenFn}">Régénérer</button><button class="ghost" onclick="document.querySelector('#${boxId}').innerHTML=''">Fermer</button></div></div>`}
function aiTextRetainCardHtml(boxId,text,retainFn,regenFn){return `<div class="card ai-suggestion"><div class="section-header"><h3>✦ Suggestion IA</h3></div><textarea class="ai-edit-area" id="${boxId}-text" style="min-height:120px;width:100%">${esc(text)}</textarea><p class="text-meta">Vous pouvez modifier ce texte avant de le retenir.</p><div class="row" style="margin-top:.6rem;flex-wrap:wrap"><button onclick="${retainFn}">Retenir</button><button class="secondary" onclick="${regenFn}">Régénérer</button><button class="ghost" onclick="document.querySelector('#${boxId}').innerHTML=''">Ignorer</button></div></div>`}
function aiListCardHtml(boxId,items,kindLabel,retainItemFn,regenFn){return `<div class="card ai-suggestion"><div class="section-header"><h3>✦ Hypothèses IA — ${esc(kindLabel)}</h3></div>${items.map((t,i)=>`<div class="ai-item"><textarea class="ai-edit-area" id="${boxId}-item-${i}" style="width:100%">${esc(t)}</textarea><div class="row" style="margin-top:.3rem"><button class="secondary" onclick="${retainItemFn}(${i},this)">Retenir cette hypothèse</button></div></div>`).join('')}<p class="text-meta" style="margin-top:.4rem">Hypothèses à discuter — aucune n’est présentée comme établie.</p><div class="row" style="margin-top:.6rem;flex-wrap:wrap"><button class="secondary" onclick="${regenFn}">Régénérer</button><button class="ghost" onclick="document.querySelector('#${boxId}').innerHTML=''">Ignorer tout</button></div></div>`}
async function saveConfigInfo(e,id){e.preventDefault();let f=Object.fromEntries(new FormData(e.target));let cur=(await api('/api/sessions')).find(x=>x.id===id);if(f.name!==cur.name&&window.configHasData){if(!confirm(`Attention : cet atelier contient déjà des réponses de participants.\n\nRenommer « ${cur.name} » en « ${f.name} » ne crée PAS un nouvel atelier : cela renomme celui-ci, avec toutes ses données existantes (participants, réponses, résultats).\n\nPour démarrer un atelier réellement vierge, utilisez plutôt « Nouveau diagnostic » depuis l’accueil.\n\nContinuer et renommer quand même ?`))return}await api('/api/sessions/'+id,{method:'PUT',body:JSON.stringify({...f,expectedParticipants:cur.expected_participants})});notice('Informations enregistrées.');configuration(id)}
async function saveExpectedParticipants(id){let raw=document.querySelector('#participants-number').value;if(raw===''||raw==null)return notice('Veuillez indiquer un nombre de participants prévus avant d’enregistrer.');let v=+raw;if(!(v>0))return notice('Le nombre de participants prévus doit être supérieur à 0.');let cur=(await api('/api/sessions')).find(x=>x.id===id);await api('/api/sessions/'+id,{method:'PUT',body:JSON.stringify({name:cur.name,organization:cur.organization,location:cur.location,date:cur.date,description:cur.description,expectedParticipants:v})});notice('Nombre de participants prévus enregistré.');configuration(id)}
function launchCollecte(id,ready){
  if(!ready){notice('Impossible d’ouvrir la collecte\n\nLe questionnaire ne contient aucun indicateur.\n\n→ Modifiez le questionnaire avant de continuer.');return}
  moderator(id)
}
function stepperHtml(done){let labels=['Préparation','Collecte','Diagnostic','Priorités','Analyse','Recommandations','Rapport'];let cur=done.findIndex(x=>!x);return `<div class="stepper">${labels.map((l,i)=>{let cls=done[i]?'done':(i===cur?'current':'');return `<span class="step ${cls}"><span class="dot">${done[i]?'✓':i+1}</span>${l}</span>`}).join('')}</div>`}
// Standalone QR Code encoder (Byte mode, versions 1-6, EC levels L/M/Q/H) — ISO/IEC 18004.
// No external dependencies; verified by round-trip decode against a reference decoder.
const generateQR=(function(){
'use strict';
const GF_EXP=new Array(512),GF_LOG=new Array(256);
(function initGF(){let x=1;for(let i=0;i<255;i++){GF_EXP[i]=x;GF_LOG[x]=i;x<<=1;if(x&0x100)x^=0x11d}for(let i=255;i<512;i++)GF_EXP[i]=GF_EXP[i-255]})();
function gfMul(a,b){return(a===0||b===0)?0:GF_EXP[GF_LOG[a]+GF_LOG[b]]}
function rsGeneratorPoly(degree){let poly=[1];for(let i=0;i<degree;i++){const next=new Array(poly.length+1).fill(0);for(let j=0;j<poly.length;j++){next[j]^=gfMul(poly[j],1);next[j+1]^=gfMul(poly[j],GF_EXP[i])}poly=next}return poly}
function rsEncode(dataBytes,ecLen){const gen=rsGeneratorPoly(ecLen);const res=dataBytes.concat(new Array(ecLen).fill(0));for(let i=0;i<dataBytes.length;i++){const coef=res[i];if(coef===0)continue;for(let j=0;j<gen.length;j++)res[i+j]^=gfMul(gen[j],coef)}return res.slice(dataBytes.length)}
const EC_L=0,EC_M=1,EC_Q=2,EC_H=3;
// RS_BLOCK_TABLE[version-1][ecLevel]=[ecCodewordsPerBlock,blocks1,dataCw1,blocks2,dataCw2] (ISO/IEC 18004 Table 9, versions 1-10)
const RS_BLOCK_TABLE=[
[[7,1,19,0,0],[10,1,16,0,0],[13,1,13,0,0],[17,1,9,0,0]],
[[10,1,34,0,0],[16,1,28,0,0],[22,1,22,0,0],[28,1,16,0,0]],
[[15,1,55,0,0],[26,1,44,0,0],[18,2,17,0,0],[22,2,13,0,0]],
[[20,1,80,0,0],[18,2,32,0,0],[26,2,24,0,0],[16,4,9,0,0]],
[[26,1,108,0,0],[24,2,43,0,0],[18,2,15,2,16],[22,2,11,2,12]],
[[18,2,68,0,0],[16,4,27,0,0],[24,4,19,0,0],[28,4,15,0,0]],
];
const VERSION_SIZE=v=>17+4*v;
const ALIGNMENT_POS=[[],[6,18],[6,22],[6,26],[6,30],[6,34]];
function bchFormat(data){let d=data<<10;const g=0x537;while(bitLength(d)-bitLength(g)>=0)d^=g<<(bitLength(d)-bitLength(g));return(data<<10|d)^0x5412}
function bitLength(n){let l=0;while(n!==0){l++;n>>>=1}return l}
const EC_INDICATOR={0:0b01,1:0b00,2:0b11,3:0b10};
const MAX_VERSION=6;
function chooseVersion(byteLen,ec){for(let v=1;v<=MAX_VERSION;v++){const blocks=RS_BLOCK_TABLE[v-1][ec];const totalData=blocks[1]*blocks[2]+blocks[3]*blocks[4];if(byteLen<=totalData-2)return v}const b=RS_BLOCK_TABLE[MAX_VERSION-1][ec];throw new Error('texte trop long pour un QR code (max ~'+(b[1]*b[2]+b[3]*b[4]-2)+' octets)')}
function encodeBytesUtf8(str){const bytes=[];for(let i=0;i<str.length;i++){let c=str.codePointAt(i);if(c>0xFFFF)i++;if(c<0x80)bytes.push(c);else if(c<0x800)bytes.push(0xC0|(c>>6),0x80|(c&0x3F));else if(c<0x10000)bytes.push(0xE0|(c>>12),0x80|((c>>6)&0x3F),0x80|(c&0x3F));else bytes.push(0xF0|(c>>18),0x80|((c>>12)&0x3F),0x80|((c>>6)&0x3F),0x80|(c&0x3F))}return bytes}
function buildDataCodewords(byteData,version,ec){const blocks=RS_BLOCK_TABLE[version-1][ec];const totalDataCw=blocks[1]*blocks[2]+blocks[3]*blocks[4];const bits=[];function put(val,len){for(let i=len-1;i>=0;i--)bits.push((val>>>i)&1)}put(0b0100,4);put(byteData.length,8);for(const b of byteData)put(b,8);const totalBits=totalDataCw*8;for(let i=0;i<4&&bits.length<totalBits;i++)bits.push(0);while(bits.length%8!==0)bits.push(0);const padBytes=[0xEC,0x11];let pi=0;while(bits.length<totalBits){put(padBytes[pi%2],8);pi++}const dataCw=[];for(let i=0;i<bits.length;i+=8){let v=0;for(let j=0;j<8;j++)v=(v<<1)|bits[i+j];dataCw.push(v)}return dataCw}
function interleave(dataCw,version,ec){const[ecLen,b1,d1,b2,d2]=RS_BLOCK_TABLE[version-1][ec];const groups=[];let offset=0;for(let i=0;i<b1;i++){groups.push(dataCw.slice(offset,offset+d1));offset+=d1}for(let i=0;i<b2;i++){groups.push(dataCw.slice(offset,offset+d2));offset+=d2}const ecGroups=groups.map(g=>rsEncode(g,ecLen));const maxData=Math.max(d1,b2?d2:0);const result=[];for(let i=0;i<maxData;i++)for(const g of groups)if(i<g.length)result.push(g[i]);for(let i=0;i<ecLen;i++)for(const g of ecGroups)result.push(g[i]);return result}
function buildMatrix(version,ec,maskPattern,finalCodewords){
const N=VERSION_SIZE(version);const mat=Array.from({length:N},()=>new Array(N).fill(null));const isFn=Array.from({length:N},()=>new Array(N).fill(false));
function setFn(r,c,v){if(r>=0&&r<N&&c>=0&&c<N){mat[r][c]=v;isFn[r][c]=true}}
function placeFinder(r,c){for(let dr=-1;dr<=7;dr++)for(let dc=-1;dc<=7;dc++){const rr=r+dr,cc=c+dc;if(rr<0||rr>=N||cc<0||cc>=N)continue;const inRing=(dr>=0&&dr<=6&&dc>=0&&dc<=6)&&(dr===0||dr===6||dc===0||dc===6);const inCore=dr>=2&&dr<=4&&dc>=2&&dc<=4;const val=(dr>=0&&dr<=6&&dc>=0&&dc<=6)?(inRing||inCore):false;setFn(rr,cc,val)}}
placeFinder(0,0);placeFinder(0,N-7);placeFinder(N-7,0);
for(let i=8;i<N-8;i++){setFn(6,i,i%2===0);setFn(i,6,i%2===0)}
const pos=ALIGNMENT_POS[version-1];
for(const r of pos)for(const c of pos){if((r<=8&&c<=8)||(r<=8&&c>=N-9)||(r>=N-9&&c<=8))continue;for(let dr=-2;dr<=2;dr++)for(let dc=-2;dc<=2;dc++){const ring=Math.max(Math.abs(dr),Math.abs(dc));setFn(r+dr,c+dc,ring!==1)}}
setFn(4*version+9,8,true);
for(let i=0;i<=14;i++){if(i<6)setFn(i,8,false);else if(i<8)setFn(i+1,8,false);else setFn(N-15+i,8,false);if(i<8)setFn(8,N-i-1,false);else if(i<9)setFn(8,15-i-1+1,false);else setFn(8,15-i-1,false)}
function maskAt(r,c){switch(maskPattern){case 0:return(r+c)%2===0;case 1:return r%2===0;case 2:return c%3===0;case 3:return(r+c)%3===0;case 4:return(Math.floor(r/2)+Math.floor(c/3))%2===0;case 5:return(r*c)%2+(r*c)%3===0;case 6:return((r*c)%2+(r*c)%3)%2===0;case 7:return((r+c)%2+(r*c)%3)%2===0}return false}
const bits=[];for(const cw of finalCodewords)for(let i=7;i>=0;i--)bits.push((cw>>>i)&1);
let bitIdx=0,dir=-1,col=N-1;
while(col>0){if(col===6)col--;for(let i=0;i<N;i++){const row=dir===-1?N-1-i:i;for(const c of[col,col-1]){if(!isFn[row][c]){const bit=bitIdx<bits.length?bits[bitIdx]:0;bitIdx++;const m=maskAt(row,c);mat[row][c]=!!bit!==m}}}dir=-dir;col-=2}
const fmtData=(EC_INDICATOR[ec]<<3)|maskPattern;const fmtBits=bchFormat(fmtData);
for(let i=0;i<=14;i++){const mod=((fmtBits>>i)&1)===1;if(i<6)mat[i][8]=mod;else if(i<8)mat[i+1][8]=mod;else mat[N-15+i][8]=mod;if(i<8)mat[8][N-i-1]=mod;else if(i<9)mat[8][15-i-1+1]=mod;else mat[8][15-i-1]=mod}
mat[N-8][8]=true;
return mat}
function penaltyScore(mat){const N=mat.length;let score=0;
for(let r=0;r<N;r++){let runLen=1;for(let c=1;c<N;c++){if(mat[r][c]===mat[r][c-1])runLen++;else{if(runLen>=5)score+=3+(runLen-5);runLen=1}}if(runLen>=5)score+=3+(runLen-5)}
for(let c=0;c<N;c++){let runLen=1;for(let r=1;r<N;r++){if(mat[r][c]===mat[r-1][c])runLen++;else{if(runLen>=5)score+=3+(runLen-5);runLen=1}}if(runLen>=5)score+=3+(runLen-5)}
for(let r=0;r<N-1;r++)for(let c=0;c<N-1;c++){const v=mat[r][c];if(v===mat[r][c+1]&&v===mat[r+1][c]&&v===mat[r+1][c+1])score+=3}
const pattern=[true,false,true,true,true,false,true];
function matchAt(arr,i){for(let k=0;k<7;k++)if(arr[i+k]!==pattern[k])return false;return true}
for(let r=0;r<N;r++)for(let c=0;c<=N-7;c++){if(matchAt(mat[r].slice(c,c+7),0))score+=40}
for(let c=0;c<N;c++)for(let r=0;r<=N-7;r++){const col=[];for(let k=0;k<7;k++)col.push(mat[r+k][c]);if(matchAt(col,0))score+=40}
let dark=0;for(let r=0;r<N;r++)for(let c=0;c<N;c++)if(mat[r][c])dark++;
score+=Math.floor(Math.abs(Math.round((dark*100)/(N*N))-50)/5)*10;
return score}
return function generateQR(text,ecLevel){
const ec={L:EC_L,M:EC_M,Q:EC_Q,H:EC_H}[ecLevel||'M'];
const byteData=encodeBytesUtf8(text);
const version=chooseVersion(byteData.length,ec);
const dataCw=buildDataCodewords(byteData,version,ec);
const finalCw=interleave(dataCw,version,ec);
let best=null,bestScore=Infinity;
for(let mask=0;mask<8;mask++){const mat=buildMatrix(version,ec,mask,finalCw);const s=penaltyScore(mat);if(s<bestScore){bestScore=s;best=mat}}
return best.map(row=>row.map(v=>!!v))}
})();
function qrSvg(link){let mat;try{mat=generateQR(link,'M')}catch(e){return `<p class="error">${esc(e.message)}</p>`}let n=mat.length,quiet=4,size=n+2*quiet,rects='';for(let r=0;r<n;r++)for(let c=0;c<n;c++)if(mat[r][c])rects+=`<rect x="${c+quiet}" y="${r+quiet}" width="1" height="1"/>`;return `<svg viewBox="0 0 ${size} ${size}" shape-rendering="crispEdges">${rects}</svg>`}
function copyLink(link){navigator.clipboard.writeText(link).then(()=>notice('Lien copié.')).catch(()=>notice('Copie impossible : sélectionnez le lien.'))}
async function moderator(id){let [a,w,q]=await Promise.all([api('/api/sessions/'+id+'/analysis'),api('/api/sessions/'+id+'/workshop-data'),api('/api/sessions/'+id+'/qualitative-data')]);let link=location.origin+'/?session='+id;let done=[true,a.completedCount>0,w.priorities.length>0,q.entries.length>0,q.recommendations.length>0,q.recommendations.length>0,false];let progressTarget=a.session.expected_participants||a.participantCount;let pct=progressTarget?Math.round(a.completedCount/progressTarget*100):0;window.currentSessionId=id;shell('collecte','collecte',a.session.name,'Tableau de bord de l’atelier',{id,name:a.session.name,location:a.session.location,date:a.session.date,pct,statusLabel:a.session.status==='closed'?'Terminé':(a.participantCount?'Collecte '+pct+'%':'Préparation')});let primary=(!a.participantCount)?{l:'Ouvrir la collecte',a:`qr('${link}')`}:(a.completedCount<a.participantCount)?{l:'Afficher le QR',a:`qr('${link}')`}:(!w.priorities.length)?{l:'Voir le diagnostic',a:`diagnostic('${id}')`}:(!q.entries.length)?{l:'Analyser les priorités',a:`analysisPriorities('${id}')`}:(!q.recommendations.length)?{l:'Construire les recommandations',a:`recommendationsView('${id}')`}:{l:'Voir le rapport final',a:`finalReport('${id}')`};app.innerHTML=`<button class="ghost" onclick="load()">← Tous les ateliers</button><div class="card"><div class="section-header"><div><h2>${esc(a.session.name)}</h2><p class="text-meta">${sessionStatusBadge(a.session,a)}${a.session.date?' · '+esc(a.session.date):''}</p></div></div>${stepperHtml(done)}<div class="grid"><div class="metric"><span class="label">Commencés</span><b>${a.participantCount}</b></div><div class="metric"><span class="label">Validés</span><b>${a.completedCount}</b></div><div class="metric"><span class="label">Progression</span><b>${pct}%</b></div>${a.global.capacity!=null?`<div class="metric"><span class="label">Capacité globale</span><b>${fmt(a.global.capacity)}</b></div>`:''}${(a.global.consensus!=null||a.global.consensusNote)?`<div class="metric"><span class="label">Consensus global</span><b>${fmtConsensus(a.global)}</b></div>`:''}</div><div class="row" style="margin-top:1.1rem"><button onclick="${primary.a}">${primary.l}</button><button class="secondary" onclick="diagnostic('${id}')">Diagnostic</button><button class="ghost" onclick="preview('${id}')">Prévisualiser le questionnaire</button><button class="ghost" onclick="reportMetadata('${id}')">Informations de l’atelier</button><button class="ghost" onclick="finalReport('${id}')">Rapport final</button><button class="danger" onclick="removeSession('${id}','${esc(a.session.name)}',${a.participantCount},${a.completedCount})">Supprimer l’atelier</button></div></div><div class="card"><div class="section-header"><h3>Collecte</h3></div><div class="qr-panel sidebar-panel"><div class="qr">${qrSvg(link)}</div><div><p class="text-meta">Lien participant</p><div class="link-box"><span style="flex:1">${esc(link)}</span></div><div class="row" style="margin-top:.6rem"><button class="secondary" onclick="copyLink('${link}')">Copier le lien</button><button class="secondary" onclick="window.open('${link}','_blank')">Ouvrir participant</button><button class="ghost" onclick="qr('${link}')">Afficher en grand</button></div><p class="text-meta" style="margin-top:.6rem">${a.participantCount} participant${a.participantCount>1?'s':''} · ${a.completedCount} questionnaire${a.completedCount>1?'s':''} validé${a.completedCount>1?'s':''}</p></div></div></div>`}
function removeSession(id,name,started=0,completed=0){
  let n=document.querySelector('#notice');if(!n){n=document.createElement('div');n.id='notice';document.body.appendChild(n)}
  n.className='help-modal';
  n.innerHTML=`<div>
    <h2>Supprimer définitivement l’atelier ?</h2>
    <p><b>${name}</b></p>
    <p class="text-meta">${started} participant${started>1?'s':''} commencé${started>1?'s':''} · ${completed} questionnaire${completed>1?'s':''} validé${completed>1?'s':''}</p>
    <p class="help-callout"><b>Attention :</b> cette action supprime aussi tous les participants, réponses, priorités, analyses et recommandations de cet atelier, même s’il est encore en cours. Impossible à annuler.</p>
    <label>Pour confirmer, tapez le nom exact de l’atelier ci-dessus :<input type="text" id="confirm-delete-input" autocomplete="off"></label>
    <div class="row" style="margin-top:.8rem">
      <button id="confirm-delete-btn" class="danger" disabled>Confirmer la suppression</button>
      <button class="secondary" onclick="this.closest('.help-modal').remove()">Annuler</button>
    </div>
  </div>`;
  let input=n.querySelector('#confirm-delete-input'),btn=n.querySelector('#confirm-delete-btn');
  input.oninput=()=>{btn.disabled=(input.value!==name)};
  btn.onclick=async()=>{n.remove();await api('/api/sessions/'+id,{method:'DELETE'});notice('Atelier supprimé.');await load()};
}
const level=v=>v==null?'—':v<20?'':v<=39?'Loin en dessous de la moyenne':v<=59?'En dessous de la moyenne':v<=70?'Moyen':v<=80?'Au-dessus de la moyenne':'Bien au-dessus de la moyenne';
function radar(ds){let a=ds.filter(d=>d.capacity!=null),n=a.length;if(n<3)return '<p class="muted">Radar non disponible : au moins 3 domaines avec des données sont nécessaires.</p>';let cx=250,cy=235,r=170,p=(v,i)=>{let z=-Math.PI/2+i*2*Math.PI/n;return `${cx+Math.cos(z)*r*v/100},${cy+Math.sin(z)*r*v/100}`};return `<svg class="chart" viewBox="0 0 500 470"><text x="12" y="18" fill="#176b4b">■ Capacité</text><text x="120" y="18" fill="#536271">■ Consensus</text>${a.map((d,i)=>{let z=-Math.PI/2+i*2*Math.PI/n;return `<line x1="${cx}" y1="${cy}" x2="${cx+Math.cos(z)*r}" y2="${cy+Math.sin(z)*r}" stroke="#aab"/><text x="${cx+Math.cos(z)*(r+12)}" y="${cy+Math.sin(z)*(r+12)}" font-size="10">${esc(d.code||d.label).slice(0,9)}</text>`}).join('')}<polygon points="${a.map((d,i)=>p(d.capacity||0,i)).join(' ')}" fill="#176b4b55" stroke="#176b4b" stroke-width="3"/><polygon points="${a.map((d,i)=>p(d.consensus||0,i)).join(' ')}" fill="#53627144" stroke="#536271" stroke-width="3"/></svg>`}
async function diagnostic(id){let a=await api('/api/sessions/'+id+'/analysis'),w=await api('/api/sessions/'+id+'/workshop-data'),g=a.global;window.currentSessionId=id;shell('resultats','traiter',a.session.name,'Diagnostic du niveau de capacité');let progressTarget=a.session.expected_participants||a.participantCount;app.innerHTML=`<section class="card"><button class="ghost" onclick="moderator('${id}')">← Retour à l’atelier</button><h2>Diagnostic terminé</h2><p class="muted">${esc(a.session.name)} · ${a.participantCount} commencés · ${a.completedCount} validés · progression ${progressTarget?Math.round(a.completedCount/progressTarget*100):0}%</p><div class="grid"><div class="metric"><span class="label">Capacité</span><b>${fmt(g.capacity)}</b></div><div class="metric"><span class="label">Consensus</span><b>${fmtConsensus(g)}</b></div><div class="metric"><span class="label">Capacité graduée</span><b>${fmt(g.gradedCapacity)}</b></div><div class="metric"><span class="label">Consensus gradué</span><b>${fmt(g.gradedConsensus)}</b></div></div><div class="section-header" style="margin-top:1.6rem"><h3>Synthèse par domaine</h3></div><div class="table-wrap"><table><tr><th>Domaine</th><th>Capacité</th><th>Consensus</th><th>Graduées</th><th>Niveau</th><th>Réponses</th><th></th></tr>${a.domains.map(d=>`<tr><td>${esc(d.label)}</td><td>${fmt(d.capacity)}</td><td>${fmtConsensus(d)}</td><td>${d.gradedCapacity??'—'} / ${d.gradedConsensus??'—'}</td><td>${level(d.capacity)}</td><td>${d.responses}</td><td><button class="ghost" onclick="domainDiagnostic('${id}','${d.id}')">Détail</button></td></tr>`).join('')}</table></div><div class="section-header" style="margin-top:1.6rem"><h3>Priorités retenues</h3></div>${w.priorities.length?`<p>${w.priorities.length} priorité(s) sélectionnée(s).</p>`:'<p class="muted">Aucune priorité sélectionnée.</p>'}<p><button onclick="finalSummary('${id}')">Synthèse finale</button></p></section>`}
async function domainDiagnostic(sid,did){
  let a=await api('/api/sessions/'+sid+'/analysis'),w=await api('/api/sessions/'+sid+'/workshop-data'),d=a.domains.find(x=>x.id===did),max=(await api('/api/templates/'+a.session.template_id)).priority.maxPerDomain;
  let selected=new Set(w.priorities.filter(p=>p.domain_id===did).map(p=>p.indicator_id));
  let flagged=new Set((a.findings?.fragilites?.indicators||[]).map(x=>x.id));
  let gapNote='';
  if(window.__lastComparison){let cds=window.__lastComparison.categories.map(c=>c.domains.find(x=>x.id===did)).filter(x=>x&&x.capacity!=null);if(cds.length>1){let gap=Math.max(...cds.map(x=>x.capacity))-Math.min(...cds.map(x=>x.capacity));let axisField=PARTICIPANT_PROFILE_FIELDS.find(f=>f.key===window.__lastComparison.axis);gapNote=`<p class="text-meta">Écart de capacité entre catégories (${esc(axisField?axisField.label:window.__lastComparison.axis)}) sur ce domaine : ${fmt(gap)} points.</p>`}}
  app.innerHTML=`<section class="card"><button class="secondary" onclick="diagnostic('${sid}')">← Retour</button><h2>${esc(d.label)}</h2><p>Sélectionnez jusqu’à ${max} priorités : la décision reste humaine.</p>${gapNote}<table><tr><th>Rang (plus faible en 1er) / Référence</th><th>Capacité</th><th>Consensus</th><th>Graduation</th><th>Distribution</th><th></th></tr>${[...d.indicators].sort((x,y)=>(x.capacity??999)-(y.capacity??999)).map((i,n)=>`<tr><td>${n+1}. ${esc(i.label)}${flagged.has(i.id)?' <span style="background:var(--red-50);color:var(--red-600);border-radius:6px;padding:.1rem .4rem;font-size:.75rem;margin-left:.4rem;white-space:nowrap">À examiner en priorité</span>':''}</td><td>${fmt(i.capacity)}</td><td>${fmtConsensus(i)}</td><td>${i.gradedCapacity??'—'} / ${i.gradedConsensus??'—'}</td><td>${Object.entries(i.distribution).map(x=>x.join(':')).join(' ')}</td><td>${selected.has(i.id)?`<button class="secondary" onclick="removePriority('${sid}','${did}','${i.id}')">Retirer</button>`:`<button onclick="addPriority('${sid}','${did}','${i.id}',${max},${selected.size})">Sélectionner</button>`}</td></tr>`).join('')}</table></section>`;
}
async function addPriority(s,d,i,max,count){if(count>=max)return notice('Le nombre maximum de priorités pour ce domaine est atteint. Retirez d’abord une priorité.');await api('/api/sessions/'+s+'/priorities',{method:'POST',body:JSON.stringify({domainId:d,indicatorId:i,votes:1})});domainDiagnostic(s,d)};async function removePriority(s,d,i){await api('/api/sessions/'+s+'/priorities/'+i,{method:'DELETE'});domainDiagnostic(s,d)};
async function finalSummary(s){
  let [a,q]=await qualitative(s);
  let retained=q.entries.filter(x=>x.validation_status==='RETENU');
  app.innerHTML=`<section class="card"><button class="secondary" onclick="diagnostic('${s}')">← Retour</button><h2>Synthèse finale</h2>
    <h3>A · Participation</h3><p>${a.participantCount} commencé(s) · ${a.completedCount} validé(s)</p>${participantProfileHtml(a.participantProfile)}
    <h3>B · Diagnostic</h3><p>Capacité ${fmt(a.global.capacity)} · consensus ${fmtConsensus(a.global)} · gradués ${fmt(a.global.gradedCapacity)} / ${fmt(a.global.gradedConsensus)}</p>${domainsTableRows(a.domains)}
    <h3>C · Forces</h3><p class="text-meta">Constats chiffrés, pas des causes.</p>${findingsForcesHtml(a.findings)}
    <h3>D · Fragilités / points de vigilance</h3>${findingsFragilitesHtml(a.findings)}${findingsVigilanceHtml(a.findings)}
    ${window.__lastComparison?`<h3>E · Analyse de sous-populations</h3>${comparisonSummaryHtml()}`:''}
    <h3>F · Priorités retenues</h3><p>${q.priorities.length} priorité(s).</p>${q.priorities.map(p=>`<p>${esc(p.domain_label)} — ${esc(p.indicator_label)}</p>`).join('')}
    <h3>G · Analyses</h3>${q.priorities.map(p=>{let an=q.analyses.find(x=>x.priority_id===p.id),e=retained.filter(x=>x.priority_id===p.id);return `<section><h4>${esc(p.domain_label)} — ${esc(p.indicator_code)}</h4><p>${esc(p.indicator_label)}</p><p><b>Constat :</b> ${esc(an?.problem||'Analyse à compléter')}</p><p><b>Causes :</b> ${e.filter(x=>x.kind==='cause').map(x=>esc(x.content)).join(' ; ')||'—'}</p><p><b>Conséquences :</b> ${e.filter(x=>x.kind==='consequence').map(x=>esc(x.content)).join(' ; ')||'—'}</p><p><b>Leviers :</b> ${e.filter(x=>x.kind==='lever').map(x=>esc(x.content)).join(' ; ')||'—'}</p></section>`}).join('')||'<p class="muted">Aucune priorité.</p>'}
    <h3>H · Recommandations retenues</h3>${q.recommendations.filter(x=>x.status==='Retenue').map(x=>`<p><b>${esc(x.title)}</b> — ${esc(x.description)}</p>`).join('')||'<p class="muted">Aucune.</p>'}
    <h3>I · Formations / plan d'action</h3>${[...q.trainingTopics,...q.recommendations.filter(x=>x.category==='Formation').map(x=>({title:x.title,need_text:x.description}))].map(x=>`<p><b>${esc(x.title)}</b> — ${esc(x.need_text||'—')}</p>`).join('')||'<p class="muted">Aucune.</p>'}
  </section>`;
}
function qr(link){document.querySelector('.app-shell').classList.add('participant-mode');app.innerHTML=`<section class="card">${back}<h2>Projection QR code</h2><p class="muted">Vue plein écran pour vidéoprojecteur. Lien local : non accessible depuis un téléphone hors réseau.</p><div class="qr" style="max-width:420px;margin:1.5rem auto">${qrSvg(link)}</div><div class="link-box" style="max-width:420px;margin:0 auto">${esc(link)}</div></section>`}
let participantName='';let participantAnonymous=false;
async function preview(sid){let a=await api('/api/sessions/'+sid+'/analysis'),t=await api('/api/templates/'+a.session.template_id);window.currentSessionId=sid;shell('questionnaire','config',a.session.name,'Aperçu du questionnaire');page(sid,null,t,a.session,{},0,true)};async function join(sid){
  document.querySelector('.app-shell').classList.add('participant-mode');participantName='';participantProfile={};
  let stored=null;try{stored=JSON.parse(localStorage.getItem(participantKey(sid))||'null')}catch(_){}
  participantAnonymous=!!(stored&&stored.anonymous);
  if(stored&&stored.completed)return participantDoneScreen(sid,stored.pid);
  let pid=stored&&stored.pid;
  if(!pid){let p=await api('/api/sessions/'+sid+'/participants',{method:'POST',body:'{}'});pid=p.id;try{localStorage.setItem(participantKey(sid),JSON.stringify({pid,completed:false,anonymous:participantAnonymous}))}catch(_){}}
  let d=await api('/api/participant?session='+sid+'&participant='+pid);
  if(!d.participant){try{localStorage.removeItem(participantKey(sid))}catch(_){}return join(sid)}
  if(d.participant.status==='completed'){try{localStorage.setItem(participantKey(sid),JSON.stringify({pid,completed:true,anonymous:participantAnonymous}))}catch(_){}return participantDoneScreen(sid,pid)}
  participantAnonymous=d.participant.anonymous!=null?!!d.participant.anonymous:participantAnonymous;
  participantName=participantAnonymous?'':(d.participant.display_name||'');
  participantProfile={};for(const f of PARTICIPANT_PROFILE_FIELDS)participantProfile[f.key]=d.participant[f.col]||'';
  page(sid,pid,d.template,d.session,d.responses,resumeDomainIndex(d.template,d.responses),false);
}
const PARTICIPANT_PROFILE_FIELDS=[
  {key:'participantType',col:'participant_type',label:'Type de participant',options:['Institutionnel','Individuel']},
  {key:'profile',col:'profile',label:'Profil',options:['ONG','Administration','Université','Secteur privé','Étudiant','Professionnel','Autre']},
  {key:'sex',col:'sex',label:'Sexe',options:['Homme','Femme']},
  {key:'ageRange',col:'age_range',label:'Tranche d’âge',options:['18–24 ans','25–39 ans','40–54 ans','55–64 ans','65 ans et plus']},
  {key:'educationLevel',col:'education_level',label:'Niveau de scolarisation',options:['BFEM','BAC','Licence','Master / DEA','Doctorat','Autre']},
];
let participantProfile={};
async function setParticipantProfile(key,value){participantProfile[key]=value;if(ctx&&ctx.pid&&!ctx.pre){try{await api('/api/participants/'+ctx.pid,{method:'PUT',body:JSON.stringify({[key]:value})})}catch(_){}}}
function resumeDomainIndex(t,r){let ds=activeDomains(t);for(let n=0;n<ds.length;n++){if(ds[n].indicators.some(i=>r[i.id]===undefined))return n}return Math.max(0,ds.length-1)}
function scaleLegend(t){let min=+t.scale.min,max=+t.scale.max,labels=t.scale.labels||{},parts=Array.from({length:max-min+1},(_,k)=>max-k).map(v=>labels[v]?`${v} = ${esc(labels[v])}`:null).filter(Boolean);return parts.length?`<div class="scale-legend"><b>Échelle de notation :</b> ${parts.join(' | ')}</div>`:''}
async function setParticipantName(v){participantName=v;if(ctx&&ctx.pid&&!ctx.pre){try{await api('/api/participants/'+ctx.pid,{method:'PUT',body:JSON.stringify({displayName:v})})}catch(_){}}}
async function setAnonymous(v){participantAnonymous=v;if(v){await setParticipantName('')}try{localStorage.setItem(participantKey(ctx.sid),JSON.stringify({pid:ctx.pid,completed:false,anonymous:v}))}catch(_){}if(ctx&&ctx.pid&&!ctx.pre){try{await api('/api/participants/'+ctx.pid,{method:'PUT',body:JSON.stringify({anonymous:v})})}catch(_){}}page(ctx.sid,ctx.pid,ctx.t,ctx.s,ctx.r,ctx.n,ctx.pre)}
function page(sid,pid,t,s,r,n,pre){let ds=t.domains.map(d=>({...d,indicators:d.indicators.filter(i=>i.active)})).filter(d=>d.indicators.length),d=ds[n],all=ds.flatMap(x=>x.indicators);if(!d)return notice('Impossible de continuer : ce questionnaire ne contient aucune question active.');window.ctx={sid,pid,t,s,r,n,pre};let answered=all.filter(i=>r[i.id]!==undefined).length,pct=all.length?Math.round(answered/all.length*100):0;app.innerHTML=`<section class="card">${pre?`<p class="preview">Mode prévisualisation</p><button class="ghost" onclick="moderator('${sid}')">← Retour au modérateur</button>`:''}<p class="participant-header">${esc(s.name)}</p>${scaleLegend(t)}${!pre&&n===0?`<label class="checkbox-row"><input type="checkbox" ${participantAnonymous?'checked':''} onchange="setAnonymous(this.checked)"> Participer anonymement</label>${participantAnonymous?'':`<label>Nom ou Organisation du Participant<input value="${esc(participantName)}" placeholder="Ex: M. Sow - Responsable Suivi-Évaluation" onchange="setParticipantName(this.value)"></label>`}<fieldset class="participant-profile"><legend>Informations sur le participant (facultatif)</legend>${PARTICIPANT_PROFILE_FIELDS.map(f=>`<label>${esc(f.label)}<select onchange="setParticipantProfile('${f.key}',this.value)"><option value="">—</option>${f.options.map(o=>`<option value="${esc(o)}" ${participantProfile[f.key]===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`).join('')}</fieldset>`:''}<div class="domain-bar"><h2>${n+1}. ${esc(d.label)}</h2></div><p class="text-meta domain-meta">Domaine ${n+1} / ${ds.length} · ${answered}/${all.length} réponses</p><div class="progress" style="margin-bottom:1.2rem"><span style="width:${pct}%"></span></div>${d.indicators.map((i,qi)=>`<div class="q-row"><label>${n+1}.${qi+1} ${esc(i.label)}${i.required?' *':''}</label>${field(i,r[i.id],pre)}</div>`).join('')}<div class="row">${n?'<button class="secondary" onclick="nav(-1)">← Précédent</button>':(pre?'<button class="ghost" onclick="load()">← Retour à l’accueil</button>':'')}${n<ds.length-1?`<button class="block" onclick="${pre?'nav(1)':'nextDomain()'}">Domaine suivant →</button>`:`<button class="block" onclick="${pre?`moderator('${sid}')`:'finish()'}">${pre?'← Retour au modérateur':'Transmettre mes Réponses au Modérateur'}</button>`}</div></section>`}
function field(i,v,pre){if(i.response_type==='numeric'){let min=+ctx.t.scale.min,max=+ctx.t.scale.max,a=Array.from({length:max-min+1},(_,n)=>max-n);return `<div class="scale-options">${a.map(x=>`<label class="scale-opt"><input type="radio" name="f_${i.id}" value="${x}" ${String(x)===String(v)?'checked':''} onchange="answer('${i.id}',this.value,'numeric')"><span class="scale-num">${x}</span></label>`).join('')}</div>`}return `<input value="${esc(v||'')}" onchange="answer('${i.id}',this.value,'${i.response_type}')">`};function answer(i,v,type){ctx.r[i]=type==='numeric'?+v:v;let all=ctx.t.domains.flatMap(d=>d.indicators.filter(x=>x.active)),answered=all.filter(x=>ctx.r[x.id]!==undefined).length,pct=all.length?Math.round(answered/all.length*100):0,meta=app.querySelector('.domain-meta');if(meta)meta.textContent=meta.textContent.replace(/\d+\/\d+ réponses/,`${answered}/${all.length} réponses`);let bar=app.querySelector('.progress>span');if(bar)bar.style.width=pct+'%';if(!ctx.pre)api('/api/sessions/'+ctx.sid+'/responses',{method:'POST',body:JSON.stringify({participantId:ctx.pid,indicatorId:i,value:ctx.r[i],valueType:type})})};function nav(d){page(ctx.sid,ctx.pid,ctx.t,ctx.s,ctx.r,ctx.n+d,ctx.pre)};
function activeDomains(t){return t.domains.map(d=>({...d,indicators:d.indicators.filter(i=>i.active)})).filter(d=>d.indicators.length)}
