  box.innerHTML=`<div class="table-wrap"><table><tr><th>Catégorie</th><th>N</th><th>Capacité</th><th>Consensus</th><th>Capacité graduée</th><th>Consensus gradué</th></tr>${r.categories.map(c=>`<tr><td>${esc(c.value)}</td><td>${c.N}</td><td>${fmt(c.capacity)}</td><td>${c.consensusNote==='single_respondent'?'Non calculable':fmt(c.consensus)}</td><td>${fmt(c.gradedCapacity)}</td><td>${fmt(c.gradedConsensus)}</td></tr>`).join('')}</table></div>${bars(r.categories.map(c=>({label:c.value,code:c.value,capacity:c.capacity,consensus:c.consensus,gradedCapacity:c.gradedCapacity,gradedConsensus:c.gradedConsensus})),'standard')}`;
