function shortLabel(d){let c=(d.code||'').trim();if(/^[a-zA-Zà-ÿÀ-ß]{2,10}$/.test(c))return c.toUpperCase();let stop=new Set(['de','des','du','la','le','les','et','en','au','aux','à','a','l']);let words=(d.label||'').trim().split(/\s+/).filter(w=>w&&!stop.has(w.toLowerCase().replace(/[’']/,'')));if(!words.length)words=(d.label||'').trim().split(/\s+/).filter(Boolean);if(words.length>=2)return words.slice(0,4).map(w=>w[0].toUpperCase()).join('');return (d.label||'').slice(0,4).toUpperCase()}
function graduatedGrid(ds){let q=cohort(ds);let pts=q.a.filter(d=>d.consensus!=null);if(!pts.length)return '<h3>Grille graduée capacité / consensus</h3><p class="muted">Pas encore de données disponibles pour la grille graduée.</p>';let left=90,top=54,plotW=380,plotH=290,bottom=top+plotH,right=left+plotW;let sx=v=>left+(v/100)*plotW,sy=v=>bottom-(v/100)*plotH;let ticks=[0,20,40,60,80,100];let avgCap=pts.reduce((x,d)=>x+d.capacity,0)/pts.length,avgCons=pts.reduce((x,d)=>x+d.consensus,0)/pts.length;let rank=new Map(pts.map((d,i)=>i).sort((x,y)=>(pts[x].capacity+pts[x].consensus)-(pts[y].capacity+pts[y].consensus)).map((idx,r)=>[idx,r]));return `<h3>Grille graduée capacité / consensus</h3><svg class="chart" viewBox="0 0 520 400"><rect x="${left}" y="${top}" width="${plotW}" height="${plotH}" fill="#e9e9e9" stroke="#000"/>${ticks.map(v=>`<line x1="${sx(v)}" y1="${top}" x2="${sx(v)}" y2="${bottom}" stroke="#bbb"/><line x1="${left}" y1="${sy(v)}" x2="${right}" y2="${sy(v)}" stroke="#bbb"/><text x="${sx(v)}" y="${bottom+16}" font-size="10" text-anchor="middle">${v}</text><text x="${left-8}" y="${sy(v)+4}" font-size="10" text-anchor="end">${v}</text>`).join('')}<line x1="${sx(50)}" y1="${top}" x2="${sx(50)}" y2="${bottom}" stroke="#333" stroke-width="2"/><line x1="${left}" y1="${sy(50)}" x2="${right}" y2="${sy(50)}" stroke="#333" stroke-width="2"/><text x="${left+plotW/2}" y="30" font-size="13" font-weight="bold" text-anchor="middle">Positionnement des domaines</text><text x="${left+plotW/2}" y="${bottom+34}" font-size="12" font-weight="bold" text-anchor="middle">Capacité</text><text x="16" y="${top+plotH/2}" font-size="12" font-weight="bold" text-anchor="middle" transform="rotate(-90 16 ${top+plotH/2})">Consensus</text><text x="${left+8}" y="${top+16}" font-size="9">Faible capacité / consensus élevé</text><text x="${right-8}" y="${top+16}" font-size="9" text-anchor="end">Capacité élevée / consensus élevé</text><text x="${left+8}" y="${bottom-6}" font-size="9">Faible capacité / consensus faible</text><text x="${right-8}" y="${bottom-6}" font-size="9" text-anchor="end">Capacité élevée / consensus faible</text>${(()=>{let dirs=[[11,-9],[11,11],[-11,-9],[-11,11]];return pts.map((d,i)=>{let cx=sx(d.capacity),cy=sy(d.consensus),num=i+1,[dx,dy]=dirs[rank.get(i)%4],lx=cx+dx,ly=cy+dy+(dy>0?4:0),anchor=dx>0?'start':'end';return `<polygon class="graphbar" data-detail="${num} — ${esc(d.label)} | Capacité ${fmt(d.capacity)} | Consensus ${fmtConsensus(d)}" points="${cx},${cy-6} ${cx+6},${cy} ${cx},${cy+6} ${cx-6},${cy}" fill="#000080"/><text x="${lx}" y="${ly}" font-size="11" font-weight="bold" text-anchor="${anchor}" fill="#000080"><title>${esc(d.label)}</title>${esc(shortLabel(d))}</text>`}).join('')})()}${(()=>{let avgX=sx(avgCap),avgY=sy(avgCons);let cands=[[22,-18,'start'],[22,22,'start'],[-22,-18,'end'],[-22,22,'end']];let labelW=92,labelH=12;let scored=cands.map(([dx,dy,anchor])=>{let lx=avgX+dx,ly=avgY+dy,boxLeft=anchor==='start'?lx:lx-labelW,boxRight=anchor==='start'?lx+labelW:lx,boxTop=ly-labelH,boxBottom=ly+4,inBounds=boxLeft>=left+2&&boxRight<=right-2&&boxTop>=top+2&&boxBottom<=bottom-2,minDist=Math.min(...pts.map(d=>{let px=sx(d.capacity),py=sy(d.consensus),nx=Math.max(boxLeft,Math.min(px,boxRight)),ny=Math.max(boxTop,Math.min(py,boxBottom));return Math.hypot(px-nx,py-ny)}));return {dx,dy,anchor,lx,ly,inBounds,minDist}}).sort((a,b)=>(b.inBounds-a.inBounds)||(b.minDist-a.minDist));let best=scored[0];return `<line x1="${avgX}" y1="${avgY}" x2="${avgX+best.dx*.7}" y2="${avgY+best.dy*.7}" stroke="#000" stroke-width=".6"/><polygon points="${avgX-5},${avgY} ${avgX},${avgY-5} ${avgX+5},${avgY} ${avgX},${avgY+5}" fill="#fff" stroke="#000" stroke-width="2"/><text x="${best.lx}" y="${best.ly}" font-size="11" font-weight="bold" text-anchor="${best.anchor}">Moyenne générale</text>`})()}</svg><p class="muted small">${pts.map((d,i)=>`<b>${i+1}</b> ${esc(d.label)}`).join(' · ')}</p>`}
function cohortChart(ds){let a=ds.filter(d=>d.capacity!=null);if(!a.length)return '<h3>Analyse comparative — cohorte des domaines</h3><p class="muted">Pas encore de données disponibles pour l’analyse de cohorte.</p>';let q=cohort(ds);let mc=a.reduce((x,d)=>x+d.capacity,0)/a.length,consA=a.filter(d=>d.consensus!=null),ms=consA.length?consA.reduce((x,d)=>x+d.consensus,0)/consA.length:null;let all=[...a,{label:'Moyen',code:'Moyen',capacity:mc,consensus:ms,gradedCapacity:q.cap,gradedConsensus:q.cons}];let w=Math.min(820,Math.max(760,80+all.length*130)),h=430,left=60,top=78,bottom=330,plotW=w-left-40,step=plotW/all.length,bw=step*.32;let axisMin=20,axisMax=100,scaleY=v=>bottom-((v-axisMin)/(axisMax-axisMin))*(bottom-top);let ticks=[20,40,60,80,100];let pts=all.map((d,i)=>({x:left+i*step+step*.12+bw+2,cap:d.gradedCapacity,cons:d.gradedConsensus}));let capLine=pts.filter(p=>p.cap!=null).map(p=>`${p.x},${scaleY(p.cap)}`).join(' ');let consLine=pts.filter(p=>p.cons!=null).map(p=>`${p.x},${scaleY(p.cons)}`).join(' ');return `<h3>Analyse comparative — cohorte des domaines</h3><p class="muted small">Notes standardisées (barres) et notes graduées (courbes) de chaque domaine, avec la moyenne de la cohorte (dernière colonne).</p><svg class="chart" viewBox="0 0 ${w} ${h}"><rect x="${left}" y="${top}" width="${plotW}" height="${bottom-top}" fill="#e9e9e9" stroke="#000"/>${ticks.map(v=>`<line x1="${left}" y1="${scaleY(v)}" x2="${left+plotW}" y2="${scaleY(v)}" stroke="#bbb"/><text x="${left-8}" y="${scaleY(v)+4}" font-size="11" text-anchor="end">${v}</text>`).join('')}<text x="${left+plotW/2}" y="22" font-size="15" font-weight="bold" text-anchor="middle">Notes standardisées et graduées — cohorte des domaines</text><rect x="${left}" y="36" width="12" height="12" fill="#9999FF"/><text x="${left+16}" y="46" font-size="11">Capacité standardisée</text><rect x="${left+190}" y="36" width="12" height="12" fill="#993366"/><text x="${left+206}" y="46" font-size="11">Consensus standardisé</text><line x1="${left+400}" y1="42" x2="${left+430}" y2="42" stroke="#800000" stroke-width="2.5"/><text x="${left+436}" y="46" font-size="11">Capacité graduée</text><line x1="${left+620}" y1="42" x2="${left+650}" y2="42" stroke="#0000ff" stroke-width="2.5"/><text x="${left+656}" y="46" font-size="11">Consensus gradué</text>${all.map((d,i)=>{let x=left+i*step,c=d.capacity,s=d.consensus,cv=Math.max(axisMin,c||0),sv=Math.max(axisMin,s||0),name=esc(d.label),short=esc(shortLabel(d)),meta=`${name} | Capacité ${fmt(c)} | Consensus ${fmt(s)} | Capacité graduée ${d.gradedCapacity??'—'} | Consensus gradué ${d.gradedConsensus??'—'}`;return `<rect class="graphbar" data-detail="${meta}" x="${x+step*.12}" y="${scaleY(cv)}" width="${bw}" height="${bottom-scaleY(cv)}" fill="#9999FF" stroke="#000"/><rect class="graphbar" data-detail="${meta}" x="${x+step*.12+bw+4}" y="${scaleY(sv)}" width="${bw}" height="${bottom-scaleY(sv)}" fill="#993366" stroke="#000"/><text x="${x+step*.12+bw+2}" y="${bottom+16}" font-size="11" text-anchor="end" font-weight="${d.label==='Moyen'?'bold':'normal'}" transform="rotate(-40 ${x+step*.12+bw+2} ${bottom+16})"><title>${name}</title>${short}</text>`}).join('')}<polyline points="${capLine}" fill="none" stroke="#800000" stroke-width="2.5"/>${pts.filter(p=>p.cap!=null).map(p=>{let y=scaleY(p.cap);return `<polygon points="${p.x},${y-6} ${p.x+6},${y+5} ${p.x-6},${y+5}" fill="#800000"/>`}).join('')}<polyline points="${consLine}" fill="none" stroke="#0000ff" stroke-width="2.5"/>${pts.filter(p=>p.cons!=null).map(p=>{let y=scaleY(p.cons);return `<line x1="${p.x-5}" y1="${y-5}" x2="${p.x+5}" y2="${y+5}" stroke="#0000ff" stroke-width="2"/><line x1="${p.x-5}" y1="${y+5}" x2="${p.x+5}" y2="${y-5}" stroke="#0000ff" stroke-width="2"/>`}).join('')}<text x="${left+plotW/2}" y="${h-8}" font-size="13" font-weight="bold" text-anchor="middle">Domaines</text></svg>`}
function visual(ds){let a=ds.filter(d=>d.capacity!=null);if(!a.length)return '<section class="graphs"><p class="muted">Pas encore de données suffisantes pour la restitution graphique EPC.</p></section>';return `<section class="graphs"><h3>Vue synthétique</h3><p class="muted small">Radar global : vue complémentaire, ne remplace pas les graphiques EPC ci-dessous.</p>${radar(ds)}<h3>Notes standardisées par domaine</h3>${bars(ds,'standard',true)}<h3>Notes graduées par domaine</h3>${bars(ds,'graded',true)}${graduatedGrid(ds)}${cohortChart(ds)}<div class="legend">20–39 : Loin en dessous · 40–59 : En dessous · 60–70 : Moyen · 71–80 : Au-dessus · 81–100 : Bien au-dessus</div></section>`}
function bars(ds,mode='standard',withMean=false){let grad=mode==='graded';let a=ds.filter(d=>d.capacity!=null);if(!a.length)return '<p class="muted">Pas encore de données disponibles.</p>';if(withMean){let mc=a.reduce((x,d)=>x+d.capacity,0)/a.length,consA=a.filter(d=>d.consensus!=null),ms=consA.length?consA.reduce((x,d)=>x+d.consensus,0)/consA.length:null,q=cohort(ds);a=[...a,{label:'Moyen',code:'Moyen',capacity:mc,consensus:ms,gradedCapacity:q.cap,gradedConsensus:q.cons}]}let w=Math.min(820,Math.max(760,80+a.length*130)),h=430,left=60,top=64,bottom=330,plotW=w-left-40,step=plotW/a.length;let axisMin=20,axisMax=100,scaleY=v=>bottom-((v-axisMin)/(axisMax-axisMin))*(bottom-top);let ticks=[20,40,60,80,100];let capLabel=grad?'Capacité graduée':'Capacité standardisée',consLabel=grad?'Consensus gradué':'Consensus standardisé';let title=grad?'Notes graduées par domaine':'Notes standardisées par domaine';return `<svg class="chart" viewBox="0 0 ${w} ${h}"><rect x="${left}" y="${top}" width="${plotW}" height="${bottom-top}" fill="#e9e9e9" stroke="#000"/>${ticks.map(v=>`<line x1="${left}" y1="${scaleY(v)}" x2="${left+plotW}" y2="${scaleY(v)}" stroke="#bbb"/><text x="${left-8}" y="${scaleY(v)+4}" font-size="11" text-anchor="end">${v}</text>`).join('')}<text x="${left+plotW/2}" y="24" font-size="16" font-weight="bold" text-anchor="middle">${title}</text><rect x="${left}" y="40" width="12" height="12" fill="#9999FF"/><text x="${left+16}" y="50" font-size="11">${capLabel}</text><rect x="${left+190}" y="40" width="12" height="12" fill="#993366"/><text x="${left+206}" y="50" font-size="11">${consLabel}</text>${a.map((d,i)=>{let x=left+i*step,c=grad?d.gradedCapacity:d.capacity,s=grad?d.gradedConsensus:d.consensus,cv=Math.max(axisMin,c||0),sv=Math.max(axisMin,s||0),bw=step*.32,name=esc(d.label),short=esc(shortLabel(d)),valFmt=v=>v==null?'—':(grad?Math.round(v):fmt(v)),meta=`${name} | ${capLabel} ${fmt(c)} | ${consLabel} ${fmt(s)}`;return `<rect class="graphbar" data-detail="${meta}" x="${x+step*.12}" y="${scaleY(cv)}" width="${bw}" height="${bottom-scaleY(cv)}" fill="#9999FF" stroke="#000"/><rect class="graphbar" data-detail="${meta}" x="${x+step*.12+bw+4}" y="${scaleY(sv)}" width="${bw}" height="${bottom-scaleY(sv)}" fill="#993366" stroke="#000"/><text x="${x+step*.12+bw/2}" y="${scaleY(cv)-6}" font-size="11" text-anchor="middle">${valFmt(c)}</text><text x="${x+step*.12+bw+4+bw/2}" y="${scaleY(sv)-6}" font-size="11" text-anchor="middle">${valFmt(s)}</text><text x="${x+step*.12+bw+2}" y="${bottom+16}" font-size="11" text-anchor="end" font-weight="${d.label==='Moyen'?'bold':'normal'}" transform="rotate(-40 ${x+step*.12+bw+2} ${bottom+16})"><title>${name}</title>${short}</text>`}).join('')}<text x="${left+plotW/2}" y="${h-8}" font-size="13" font-weight="bold" text-anchor="middle">Domaines de compétence</text></svg>`}
document.addEventListener('pointerover',e=>{let b=e.target.closest?.('.graphbar');if(!b)return;let t=document.querySelector('#chart-tip');if(!t){t=document.createElement('div');t.id='chart-tip';t.className='chart-tip';document.body.appendChild(t)}t.textContent=b.dataset.detail;t.style.display='block'});document.addEventListener('pointermove',e=>{let t=document.querySelector('#chart-tip');if(t){t.style.left=(e.clientX+14)+'px';t.style.top=(e.clientY+14)+'px'}});document.addEventListener('pointerout',e=>{if(e.target.closest?.('.graphbar')){let t=document.querySelector('#chart-tip');if(t)t.style.display='none'}});
function downloadFile(name,text,type='text/csv;charset=utf-8'){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
function csv(rows){return rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(';')).join('\n')}
function fileSlug(s){return String(s||'').normalize('NFKD').replace(/[̀-ͯ]/g,'').replace(/[^A-Za-z0-9]+/g,'-').replace(/^-+|-+$/g,'')||'sans-titre'}
function dateStamp(){return new Date().toISOString().slice(0,10)}
async function exportDiagnostic(id){let a=await api('/api/sessions/'+id+'/analysis');let base=fileSlug(a.session.name)+'_'+dateStamp();let domains=[['Domaine','Capacité standardisée','Consensus standardisé','Capacité graduée','Consensus gradué','Réponses','Niveau'],...a.domains.map(d=>[d.label,fmt(d.capacity),fmtConsensus(d),d.gradedCapacity,d.gradedConsensus,d.responses,level(d.capacity)])];let indicators=[['Domaine','Référence','Capacité','Consensus','Réponses','Manquants'],...a.domains.flatMap(d=>d.indicators.map(i=>[d.label,i.label,fmt(i.capacity),fmtConsensus(i),i.responses,i.missing]))];downloadFile(base+'.csv',csv([['DOMAINES'],...domains,[],['INDICATEURS'],...indicators]))}
const diagnosticExportBase=diagnostic;diagnostic=async id=>{await diagnosticExportBase(id);app.querySelector('.grid')?.insertAdjacentHTML('beforebegin',`<div class="row print-actions"><button class="secondary" onclick="window.print()">Imprimer / Télécharger en PDF</button><button class="secondary" onclick="exportDiagnostic('${id}')">Télécharger les CSV</button><button class="secondary" onclick="downloadIndividualResponses('${id}','xlsx')">Exporter les réponses individuelles (Excel)</button><button class="secondary" onclick="downloadIndividualResponses('${id}','csv')">Exporter les réponses individuelles (CSV)</button></div>`)};
async function downloadIndividualResponses(sid,ext){
  try{
    let r=await fetch(`/api/sessions/${sid}/individual-responses.${ext}`);
    if(!r.ok){let x=await r.json().catch(()=>({}));throw Error(x.error||'Le fichier n’a pas pu être généré.')}
    let blob=await r.blob();
    let cd=r.headers.get('Content-Disposition')||'';
    let m=cd.match(/filename=([^;]+)/);
    let filename=m?m[1].replace(/["']/g,''):`reponses-individuelles.${ext}`;
    let url=URL.createObjectURL(blob);
    let a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();
    setTimeout(()=>URL.revokeObjectURL(url),1000);
  }catch(e){notice(e.message||'Téléchargement impossible. Veuillez réessayer.')}
}
const finalSummaryExportBase=finalSummary;finalSummary=async id=>{await finalSummaryExportBase(id);app.querySelector('.card')?.insertAdjacentHTML('beforeend',`<div class="row print-actions"><button class="secondary" onclick="window.print()">Imprimer / Télécharger en PDF</button><button class="secondary" onclick="exportDiagnostic('${id}')">Télécharger les résultats CSV</button></div>`)};
async function downloadReport(sid,fmt,filenameHint){
  try{
    let r=await fetch(`/api/sessions/${sid}/report.${fmt}`);
    if(!r.ok){let x=await r.json().catch(()=>({}));throw Error(x.error||'Le fichier n’a pas pu être généré.')}
    let blob=await r.blob();
    let cd=r.headers.get('Content-Disposition')||'';
    let m=cd.match(/filename=([^;]+)/);
    let filename=m?m[1].replace(/["']/g,''):filenameHint;
    let url=URL.createObjectURL(blob);
    let a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();
    setTimeout(()=>URL.revokeObjectURL(url),1000);
  }catch(e){notice(e.message||'Téléchargement impossible. Veuillez réessayer.')}
}
const diagnosticFormatsBase=diagnostic;diagnostic=async id=>{await diagnosticFormatsBase(id);app.querySelector('.print-actions')?.insertAdjacentHTML('beforeend',`<button type="button" class="secondary" onclick="downloadReport('${id}','xlsx','diagnostic.xlsx')">Télécharger Excel</button><button type="button" class="secondary" onclick="downloadReport('${id}','docx','rapport.docx')">Télécharger Word</button>`)};
const finalFormatsBase=finalSummary;finalSummary=async id=>{await finalFormatsBase(id);let a=app.querySelectorAll('.print-actions');a[a.length-1]?.insertAdjacentHTML('beforeend',`<button type="button" class="secondary" onclick="downloadReport('${id}','xlsx','diagnostic.xlsx')">Excel</button><button type="button" class="secondary" onclick="downloadReport('${id}','docx','rapport.docx')">Word</button>`)};

/* Phase qualitative : aucune de ces données ne modifie les scores EPC. */
const statusOptions=['A discuter','Retenu par le groupe','Écarté'];
const statusValue=x=>({'A discuter':'A_DISCUTER','Retenu par le groupe':'RETENU','Écarté':'ECARTE'}[x]||x);
const statusLabel=x=>({'A_DISCUTER':'À discuter','RETENU':'Retenu par le groupe','ECARTE':'Écarté'}[x]||x);
const optionList=(items,value,label,blank='— Aucun —')=>`<option value="">${blank}</option>${items.map(x=>`<option value="${x.id}" ${x.id===value?'selected':''}>${esc(label(x))}</option>`).join('')}`;
async function qualitative(s){return Promise.all([api('/api/sessions/'+s+'/analysis'),api('/api/sessions/'+s+'/qualitative-data')])}
function priorityInfo(a,q,p){let d=a.domains.find(x=>x.id===p.domain_id),i=d?.indicators.find(x=>x.id===p.indicator_id);return {d,i,p}}
async function analysisPriorities(s){let [a,q]=await qualitative(s);app.innerHTML=`<section class="card"><button class="secondary" onclick="diagnostic('${s}')">← Retour au diagnostic</button><h2>Analyse des priorités</h2><p>${esc(a.session.name)} · Participants : ${a.participantCount} · réponses validées : ${a.completedCount} · priorités retenues : ${q.priorities.length}</p><div class="card" style="margin:1rem 0"><div class="section-header"><h3>Constats</h3></div><p class="text-meta">Lecture objective des résultats — jamais présentée comme une cause.</p><h4>Forces</h4>${findingsForcesHtml(a.findings)}<h4>Fragilités</h4>${findingsFragilitesHtml(a.findings)}<h4>Points de vigilance</h4>${findingsVigilanceHtml(a.findings)}</div>${q.priorities.length?'<p>Les résultats chiffrés sont un rappel ; les constats sont saisis et validés par le groupe.</p>':''}${q.priorities.map(p=>{let x=priorityInfo(a,q,p),an=q.analyses.find(z=>z.priority_id===p.id),n=q.entries.filter(e=>e.priority_id===p.id).length;return `<section class="domain"><h3>${esc(p.domain_label)} — ${esc(p.indicator_code)}</h3><p><b>${esc(p.indicator_label)}</b><br>${esc(p.indicator_description)}</p><p>Capacité ${fmt(x.i?.capacity)} · consensus ${fmt(x.i?.consensus)} · ${level(x.i?.capacity)} · ${n?`${n} élément(s) analysé(s)`:'Analyse à compléter'}</p><button onclick="priorityAnalysis('${s}','${p.id}')">Analyser →</button></section>`}).join('')||'<p>Aucune priorité retenue : revenez au diagnostic pour sélectionner les critères à travailler.</p>'}<div class="row"><button class="secondary" onclick="recommendationsView('${s}')">Recommandations →</button><button class="secondary" onclick="finalSummary('${s}')">Synthèse finale →</button></div></section>`}
function entryTree(entries,parent=''){return entries.filter(e=>(e.parent_id||'')===parent).map(e=>`<li><b>${esc(e.kind)}</b> — ${esc(e.content)} <em>(${esc(statusLabel(e.validation_status))})</em><div class="row"><button class="secondary" onclick="editEntry('${e.id}','${e.session_id}','${e.priority_id}')">Modifier</button><button class="secondary" onclick="newEntry('${e.session_id}','${e.priority_id}','cause','${e.id}')">+ Sous-cause</button><button class="danger" onclick="deleteEntry('${e.id}','${e.session_id}','${e.priority_id}')">Supprimer</button></div>${entryTree(entries,e.id)}</li>`).join('')}
async function priorityAnalysis(s,pid){let [a,q]=await qualitative(s),p=q.priorities.find(x=>x.id===pid),x=priorityInfo(a,q,p),an=q.analyses.find(z=>z.priority_id===pid),e=q.entries.filter(z=>z.priority_id===pid);let autoConstat=`Capacité ${fmt(x.i?.capacity)}, consensus ${fmt(x.i?.consensus)}, N=${a.completedCount}.`;app.innerHTML=`<section class="card"><button class="secondary" onclick="analysisPriorities('${s}')">← Retour aux priorités</button><h2>${esc(p.domain_label)}</h2><h3>${esc(p.indicator_code)} — ${esc(p.indicator_label)}</h3><p>Capacité : <b>${fmt(x.i?.capacity)}</b> · Consensus : <b>${fmt(x.i?.consensus)}</b></p><form onsubmit="saveProblem(event,'${s}','${pid}','${an?.id||''}')"><label>Quel problème ou constat ressort de ce résultat ?<textarea name="problem">${esc(an?.problem||autoConstat)}</textarea></label><button>Enregistrer le constat</button></form><hr><h3>Pourquoi cette situation existe-t-elle ?</h3><button onclick="newEntry('${s}','${pid}','cause')">+ Ajouter une cause</button><ul>${entryTree(e.filter(z=>z.kind==='cause'))||'<li>Analyse à compléter</li>'}</ul><h3>Quelles conséquences cette situation entraîne-t-elle ?</h3><button onclick="newEntry('${s}','${pid}','consequence')">+ Ajouter une conséquence</button><ul>${entryTree(e.filter(z=>z.kind==='consequence'))||'<li>Analyse à compléter</li>'}</ul><h3>Sur quoi peut-on agir ?</h3><button onclick="newEntry('${s}','${pid}','lever')">+ Ajouter un levier</button><ul>${entryTree(e.filter(z=>z.kind==='lever'))||'<li>Analyse à compléter</li>'}</ul><div class="row"><button class="secondary" onclick="analysisPriorities('${s}')">← Priorité précédente / liste</button><button onclick="recommendationsView('${s}','${pid}')">Construire les recommandations →</button></div></section>`}
async function saveProblem(e,s,pid,id){e.preventDefault();await api('/api/sessions/'+s+'/priority-analyses',{method:'POST',body:JSON.stringify({priorityId:pid,problem:new FormData(e.target).get('problem')})});priorityAnalysis(s,pid)}
async function newEntry(s,pid,kind,parent=''){let text=prompt(kind==='cause'?'Cause :':kind==='consequence'?'Conséquence :':'Levier :');if(!text?.trim())return;let type=kind==='cause'?prompt('Type facultatif (Cause, Cause racine potentielle, Facteur interne, Facteur externe, Hypothèse) :')||'':'';await api('/api/sessions/'+s+'/analysis-entries',{method:'POST',body:JSON.stringify({priorityId:pid,parentId:parent,kind,content:text,itemType:type,validationStatus:'A_DISCUTER'})});priorityAnalysis(s,pid)}
async function editEntry(id,s,pid){let q=await api('/api/sessions/'+s+'/qualitative-data'),e=q.entries.find(x=>x.id===id),content=prompt('Modifier le texte :',e?.content||'');if(content===null||!e)return;let status=prompt('Statut : À discuter, Retenu par le groupe ou Écarté',statusLabel(e.validation_status));await api('/api/analysis-entries/'+id,{method:'PUT',body:JSON.stringify({...e,content,validationStatus:statusValue(status)})});priorityAnalysis(s,pid)}
async function deleteEntry(id,s,pid){try{await api('/api/analysis-entries/'+id,{method:'DELETE'});notice('Élément supprimé.')}catch(err){if(confirm(err.message+'\n\nForcer la suppression ?'))await api('/api/analysis-entries/'+id+'?force=1',{method:'DELETE'});else return}priorityAnalysis(s,pid)}
async function recommendationsView(s,selected=''){let [a,q]=await qualitative(s),entries=q.entries.filter(e=>e.validation_status==='RETENU'),recs=q.recommendations;window.currentSessionId=s;shell('recommandations','analyse',a.session.name,'Recommandations retenues');app.innerHTML=`<section class="card"><button class="secondary" onclick="analysisPriorities('${s}')">← Retour aux analyses</button><h2>Recommandations</h2><form onsubmit="saveRecommendationV2(event,'${s}')"><label>Titre *<input name="title" required></label><label>Description / action proposée *<textarea name="description" required></textarea></label><label>Priorité concernée<select name="priorityId">${optionList(q.priorities,selected,x=>x.domain_label+' — '+x.indicator_label)}</select></label><label>Cause retenue<select name="causeId">${optionList(entries.filter(x=>x.kind==='cause'),' ',x=>x.content)}</select></label><label>Levier retenu<select name="leverId">${optionList(entries.filter(x=>x.kind==='lever'),' ',x=>x.content)}</select></label><label>Catégorie<select name="category">${['Formation','Organisation','Gouvernance','Ressources humaines','Ressources financières','Processus','Partenariat','Communication','Équipement / moyens','Autre'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Niveau de priorité<select name="priorityLevel">${['Haute','Moyenne','Basse','Non définie'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Responsable / acteur concerné<input name="owner"></label><label>Échéance<input name="horizon"></label><label>Commentaire<textarea name="comment"></textarea></label><button>Ajouter la recommandation</button></form><h3>Tableau de synthèse</h3><table><tr><th>Recommandation</th><th>Priorité</th><th>Catégorie</th><th>Niveau</th><th>Responsable</th><th>Statut</th><th></th></tr>${recs.map(r=>{let pr=q.priorities.find(x=>x.id===r.priority_id);return `<tr><td><b>${esc(r.title)}</b><br>${esc(r.description)}</td><td>${pr?esc(pr.domain_label+' — '+pr.indicator_label):'—'}</td><td>${esc(r.category)}</td><td>${esc(r.priority_level)}</td><td>${esc(r.owner||'—')}</td><td>${esc(r.status)}</td><td><button class="secondary" onclick="setRecommendationStatus('${s}','${r.id}')">Statut</button><button class="danger" onclick="deleteRecommendation('${s}','${r.id}')">Supprimer</button></td></tr>`}).join('')||'<tr><td colspan="7">Aucune recommandation.</td></tr>'}</table><div class="row"><button onclick="trainingView('${s}')">Besoins / thèmes de formation →</button><button class="secondary" onclick="planView('${s}')">Plan d’action →</button></div></section>`}
async function saveRecommendationV2(e,s){e.preventDefault();await api('/api/sessions/'+s+'/recommendations-v2',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});recommendationsView(s)}
async function setRecommendationStatus(s,id){let status=prompt('Statut : Proposée, Retenue ou Écartée','Proposée');if(!status)return;let q=await api('/api/sessions/'+s+'/qualitative-data'),r=q.recommendations.find(x=>x.id===id);await api('/api/recommendations-v2/'+id,{method:'PUT',body:JSON.stringify({...r,status})});recommendationsView(s)}
async function deleteRecommendation(s,id){try{await api('/api/recommendations-v2/'+id,{method:'DELETE'})}catch(e){if(confirm(e.message+'\n\nForcer la suppression ?'))await api('/api/recommendations-v2/'+id+'?force=1',{method:'DELETE'})}recommendationsView(s)}
async function trainingView(s){let q=await api('/api/sessions/'+s+'/qualitative-data'),formation=q.recommendations.filter(r=>r.category==='Formation');app.innerHTML=`<section class="card"><button class="secondary" onclick="recommendationsView('${s}')">← Retour aux recommandations</button><h2>Besoins / thèmes de formation</h2><p>Les recommandations de catégorie Formation sont reprises automatiquement ; aucun contenu de formation n’est inventé.</p><form onsubmit="saveTraining(event,'${s}')"><label>Intitulé *<input name="title" required></label><label>Besoin auquel il répond<textarea name="needText"></textarea></label><label>Public cible<input name="targetAudience"></label><label>Priorité<select name="priorityLevel"><option>Haute</option><option>Moyenne</option><option>Basse</option><option selected>Non définie</option></select></label><label>Commentaire<textarea name="comment"></textarea></label><button>Ajouter un thème de formation</button></form><h3>Recommandations Formation</h3>${formation.map(r=>`<p><b>${esc(r.title)}</b> — ${esc(r.description)} (${esc(r.status)})</p>`).join('')||'<p>Aucune.</p>'}<h3>Thèmes créés</h3>${q.trainingTopics.map(t=>`<p><b>${esc(t.title)}</b> — ${esc(t.need_text||'—')} <button class="danger" onclick="api('/api/training-topics/${t.id}',{method:'DELETE'}).then(()=>trainingView('${s}'))">Supprimer</button></p>`).join('')||'<p>Aucun.</p>'}<button onclick="planView('${s}')">Plan d’action →</button></section>`}
async function saveTraining(e,s){e.preventDefault();await api('/api/sessions/'+s+'/training-topics',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});trainingView(s)}
async function planView(s){let q=await api('/api/sessions/'+s+'/qualitative-data'),r=q.recommendations.filter(x=>x.status==='Retenue');app.innerHTML=`<section class="card"><button class="secondary" onclick="recommendationsView('${s}')">← Retour aux recommandations</button><h2>Plan d’action</h2><table><tr><th>N°</th><th>Action / recommandation</th><th>Origine</th><th>Responsable</th><th>Échéance</th><th>Priorité</th><th>Statut</th></tr>${r.map((x,n)=>`<tr><td>${n+1}</td><td>${esc(x.title)}</td><td>${esc(x.priority_id||'—')}</td><td>${esc(x.owner||'—')}</td><td>${esc(x.horizon||'—')}</td><td>${esc(x.priority_level)}</td><td>${esc(x.status)}</td></tr>`).join('')||'<tr><td colspan="7">Aucune recommandation retenue.</td></tr>'}</table><button onclick="finalSummary('${s}')">Synthèse finale →</button></section>`}
const diagnosticQualBase=diagnostic;diagnostic=async id=>{await diagnosticQualBase(id);app.querySelector('.card')?.insertAdjacentHTML('beforeend',`<div class="row"><button onclick="analysisPriorities('${id}')">Analyser les priorités →</button></div>`)};

async function reportMetadata(s){let r=await api('/api/sessions/'+s+'/report-data'),m=r.meta,session=r.analysis.session;app.innerHTML=`<section class="card"><button class="secondary" onclick="moderator('${s}')">← Retour à l’atelier</button><h2>Informations de l’atelier</h2><form onsubmit="saveReportMeta(event,'${s}')"><label>Intitulé de l’atelier *<input name="name" required value="${esc(session.name)}"></label><label>Organisation / structure<input name="organization" value="${esc(session.organization||'')}"></label><label>Lieu<input name="location" value="${esc(session.location||'')}"></label><label>Date<input name="date" value="${esc(session.date||'')}"></label><label>Animateur / facilitateur<input name="facilitator" value="${esc(m.facilitator||'')}"></label><label>Public / groupe concerné<input name="audience" value="${esc(m.audience||'')}"></label><label>Commentaire ou contexte<textarea name="context">${esc(m.context||'')}</textarea></label><label>Conclusion générale de l’atelier<textarea name="conclusion">${esc(m.conclusion||'')}</textarea></label><button>Enregistrer</button></form></section>`}
async function saveReportMeta(e,s){e.preventDefault();let x=Object.fromEntries(new FormData(e.target));await api('/api/sessions/'+s,{method:'PUT',body:JSON.stringify(x)});await api('/api/sessions/'+s+'/report-meta',{method:'POST',body:JSON.stringify(x)});finalReport(s)}
function reportMethodology(t){let scale=Object.entries(t.scale.labels||{}).sort((a,b)=>Number(a[0])-Number(b[0])).map(([n,l])=>`${n} : ${l||'non libellé'}`).join(' · ');return `Chaque participant renseigne les indicateurs selon l’échelle configurée (${t.scale.min}–${t.scale.max} : ${scale||'libellés non renseignés'}). Les réponses sont agrégées par indicateur et par domaine. La capacité exprime la moyenne standardisée sur 100 ; le consensus traduit l’homogénéité des réponses à partir de leur dispersion. Les notes sont ensuite graduées suivant la norme du questionnaire. Les participants sélectionnent collectivement les priorités, puis documentent les causes, conséquences, leviers et recommandations.`}
function reportTable(rows,headers){return `<table><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr>${rows||`<tr><td colspan="${headers.length}">Non renseigné</td></tr>`}</table>`}
async function finalReport(s){let r=await api('/api/sessions/'+s+'/report-data'),a=r.analysis,t=r.template,q=r.qualitative,m=r.meta,g=a.global,ds=a.domains.filter(d=>d.capacity!=null),priorities=q.priorities;window.currentSessionId=s;shell('rapport','restitution',a.session.name,'Rapport final');let indicatorRows=ds.flatMap(d=>d.indicators.filter(i=>i.capacity!=null).map(i=>({...i,domain:d.label}))),retained=q.entries.filter(x=>x.validation_status==='RETENU'),priorityById=Object.fromEntries(priorities.map(x=>[x.id,x]));let rankings=(list,key,dir=1)=>list.slice().sort((x,y)=>dir*((x[key]??0)-(y[key]??0))).map(x=>`<li>${esc(x.domain||x.label)}${x.domain?' — '+esc(x.label):''} : ${fmt(x[key])}</li>`).join('')||'<li>Non renseigné</li>';app.innerHTML=`<article class="report"><div class="report-actions"><button class="secondary" onclick="moderator('${s}')">← Retour à l’atelier</button><button onclick="window.print()">Imprimer / PDF</button><a href="/api/sessions/${s}/report.xlsx"><button type="button" class="secondary">Télécharger Excel</button></a></div><nav class="report-nav">${['Méthodologie','Participation','Profil','Diagnostic global','Domaines','Constats','Priorités','Analyses','Recommandations','Formations','Plan d’action','Annexes'].map(x=>`<a href="#${x.replaceAll(' ','-').replaceAll('é','e')}">${x}</a>`).join('')}</nav><section class="report-cover"><h1>DIAGNOSTIC EPC / SENEVAL</h1><h2>${esc(a.session.name)}</h2><p>${esc(a.session.organization||'Non renseigné')}<br>${esc(a.session.location||'Non renseigné')}<br>${esc(a.session.date||'Non renseigné')}</p><p>Participants : ${a.participantCount} · questionnaires validés : ${a.completedCount}${m.facilitator?`<br>Animateur / facilitateur : ${esc(m.facilitator)}`:''}</p></section><section><h2>Contexte</h2><p>${esc(m.context||'Non renseigné')}</p></section><section id="Méthodologie"><h2>Méthodologie</h2><p>${esc(reportMethodology(t))}</p></section><section id="Participation"><h2>Participation</h2><p>Participants enregistrés : ${a.participantCount} · questionnaires validés : ${a.completedCount} · incomplets : ${Math.max(0,a.participantCount-a.completedCount)} · taux de complétion : ${a.participantCount?Math.round(a.completedCount/a.participantCount*100):'—'}%</p></section><section id="Profil"><h2>Profil des participants</h2>${participantProfileHtml(a.participantProfile)}</section><section id="Diagnostic-global"><h2>Diagnostic global</h2><div class="grid"><div class="metric">Capacité standardisée <b>${fmt(g.capacity)}</b></div><div class="metric">Consensus standardisé <b>${fmtConsensus(g)}</b></div><div class="metric">Capacité graduée <b>${fmt(g.gradedCapacity)}</b></div><div class="metric">Consensus gradué <b>${fmt(g.gradedConsensus)}</b></div></div>${visual(ds)}</section><section id="Domaines"><h2>Tableau synthétique des domaines</h2>${reportTable(ds.map(d=>`<tr><td>${esc(d.label)}</td><td>${fmt(d.capacity)}</td><td>${fmtConsensus(d)}</td><td>${d.gradedCapacity??'—'}</td><td>${d.gradedConsensus??'—'}</td><td>${esc(level(d.capacity))}</td><td>${d.responses}</td></tr>`).join(''),['Domaine','Capacité','Consensus','Cap. graduée','Cons. gradué','Niveau','Répondants'])}${ds.map(d=>`<section class="report-domain"><h3>${esc(d.label)}</h3><p>Capacité ${fmt(d.capacity)} · consensus ${fmtConsensus(d)} · notes graduées ${d.gradedCapacity??'—'} / ${d.gradedConsensus??'—'} · ${esc(level(d.capacity))} · ${d.responses} répondant(s)</p>${bars(d.indicators)}${reportTable(d.indicators.map(i=>`<tr><td>${esc(i.code)}</td><td>${esc(i.label)}</td><td>${fmt(i.capacity)}</td><td>${fmtConsensus(i)}</td><td>${i.responses}</td><td>${i.missing}</td></tr>`).join(''),['Référence','Indicateur','Capacité','Consensus','Réponses','Données manquantes'])}</section>`).join('')}</section><section><h2>Lecture des résultats</h2><div class="report-columns"><div><h3>Domaines les plus faibles</h3><ol>${rankings(ds,'capacity',1)}</ol><h3>Indicateurs les plus faibles</h3><ol>${rankings(indicatorRows,'capacity',1)}</ol></div><div><h3>Domaines les plus forts</h3><ol>${rankings(ds,'capacity',-1)}</ol><h3>Indicateurs les plus forts</h3><ol>${rankings(indicatorRows,'capacity',-1)}</ol><h3>Indicateurs à faible consensus</h3><ol>${rankings(indicatorRows,'consensus',1)}</ol></div></div></section><section id="Constats"><h2>Forces / Fragilités / Points de vigilance</h2><h3>Forces</h3>${findingsForcesHtml(a.findings)}<h3>Fragilités</h3>${findingsFragilitesHtml(a.findings)}<h3>Points de vigilance</h3>${findingsVigilanceHtml(a.findings)}${window.__lastComparison?`<h3>Comparaison des sous-populations retenue</h3>${comparisonSummaryHtml()}`:''}</section><section id="Priorités"><h2>Priorités retenues par les participants</h2>${reportTable(priorities.map(p=>{let d=a.domains.find(x=>x.id===p.domain_id),i=d?.indicators.find(x=>x.id===p.indicator_id);return `<tr><td>${esc(p.domain_label)}</td><td>${esc(p.indicator_code)}</td><td>${esc(p.indicator_label)}</td><td>${fmt(i?.capacity)}</td><td>${fmt(i?.consensus)}</td></tr>`}).join(''),['Domaine','Référence','Indicateur','Capacité','Consensus'])}</section><section id="Analyses"><h2>Analyse qualitative</h2>${priorities.map(p=>{let an=q.analyses.find(x=>x.priority_id===p.id),e=retained.filter(x=>x.priority_id===p.id);return `<section><h3>${esc(p.domain_label)} — ${esc(p.indicator_code)} — ${esc(p.indicator_label)}</h3><p><b>Constat :</b> ${esc(an?.problem||'Analyse non réalisée')}</p><p><b>Causes retenues :</b> ${e.filter(x=>x.kind==='cause').map(x=>esc(x.content)).join(' ; ')||'Non renseigné'}</p><p><b>Conséquences retenues :</b> ${e.filter(x=>x.kind==='consequence').map(x=>esc(x.content)).join(' ; ')||'Non renseigné'}</p><p><b>Leviers retenus :</b> ${e.filter(x=>x.kind==='lever').map(x=>esc(x.content)).join(' ; ')||'Non renseigné'}</p></section>`}).join('')||'<p>Analyse non réalisée.</p>'}</section><section id="Recommandations"><h2>Recommandations retenues</h2>${q.recommendations.filter(x=>x.status==='Retenue').map(x=>{let p=priorityById[x.priority_id];return `<section><h3>${esc(x.title)}</h3><p>${esc(x.description)}</p><p>${esc(p?`${p.domain_label} — ${p.indicator_label}`:'Origine non renseignée')} · ${esc(x.category)} · priorité ${esc(x.priority_level)} · ${esc(x.owner||'Responsable non renseigné')} · ${esc(x.horizon||'Échéance non renseignée')}</p></section>`}).join('')||'<p>Aucune recommandation retenue.</p>'}</section><section id="Formations"><h2>Besoins / thèmes de formation</h2>${q.trainingTopics.map(x=>`<p><b>${esc(x.title)}</b> — ${esc(x.need_text||'Non renseigné')} · ${esc(x.target_audience||'Public non renseigné')} · ${esc(x.priority_level)}</p>`).join('')||'<p>Aucun thème de formation retenu.</p>'}</section><section id="Plan-d’action"><h2>Plan d’action</h2>${reportTable(q.recommendations.filter(x=>x.status==='Retenue').map((x,n)=>`<tr><td>${n+1}</td><td>${esc(x.title)}</td><td>${esc(priorityById[x.priority_id]?.indicator_label||'—')}</td><td>${esc(x.owner||'—')}</td><td>${esc(x.horizon||'—')}</td><td>${esc(x.priority_level)}</td><td>${esc(x.status)}</td></tr>`).join(''),['N°','Action / recommandation','Origine','Responsable','Échéance','Priorité','Statut'])}</section><section><h2>Conclusion générale de l’atelier</h2><p>${esc(m.conclusion||'Non renseigné')}</p></section><section id="Annexes"><h2>Annexes</h2><h3>Questionnaire utilisé</h3>${t.domains.map(d=>`<h4>${esc(d.label)}</h4><ul>${d.indicators.filter(i=>i.active).map(i=>`<li>${esc(i.code)} — ${esc(i.label)} : ${esc(i.description)}</li>`).join('')}</ul>`).join('')}<p>Échelle : ${esc(reportMethodology(t).split('. ')[0])}.</p><h3>Éléments encore à discuter</h3>${q.entries.filter(x=>x.validation_status==='A_DISCUTER').map(x=>`<p>${esc(x.kind)} — ${esc(x.content)}</p>`).join('')||'<p>Aucun.</p>'}</section></article>`}

